27.,"4\x93ne\xB7\xF9+js\r\xB0\xEE\x08%\x08\ty\xE0\xD0a\xEE\xAD\xB5\xB7:_9ktgC!.$SjMPsk)8TfsiYq/A]X/@",'LocalPlayer.UserId\n                if not userId then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "Player not ready!", Duration = 2 })\n                    return\n                end\n                local userData = Data and Data:FindFirstChild(tostring(userId))\n                if not userData then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "User data not found!", Duration = 2 })\n                    return\n                end\n                local essenceOrb = userData:FindFirstChild("EssenceOrb")\n                if not essenceOrb or not (typeof(essenceOrb) == "Instance" and essenceOrb:IsA("NumberValue")) then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "EssenceOrb not found!", Duration = 2 })\n                    return\n                end\n                if essenceOrb.Value <= 0 then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "Not enough EssenceOrb!", Duration = 2 })\n                    return\n                end\n                if not Events or not Events.UpgradeSkill then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "UpgradeSkill remote not found!", Duration = 2 })\n                    return\n                end\n\n                NexusState.upgradeSkill.teleported = false\n                NexusState.upgradeSkill.oldPosition = nil\n                if NexusState.upgradeSkill.method == "Teleport" then\n                    local npc = Workspace:FindFirstChild("NPC")\n                    if npc then\n                        local func = npc:FindFirstChild("Function")\n                        if func then\n                            local zengTianguo = func:FindFirstChild("Zeng Tianguo")\n                            if typeof(zengTianguo) == "Instance" and zengTianguo:IsA("Model") then\n                                local hrp = zengTianguo:FindFirstChild("HumanoidRootPart")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            NexusState.upgradeSkill.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.upgradeSkill.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.upgradeSkill.teleported then\n                        NexusLib:Notify({ Title = "Upgrade Skill", Message = "Could not find Zeng Tianguo, teleport failed. Continuing anyway.", Duration = 3 })\n                    end\n                end\n\n                local success, err = pcall(function()\n                    return Events.UpgradeSkill:InvokeServer(selectedSkill)\n                end)\n\n                if NexusState.upgradeSkill.teleported and NexusState.upgradeSkill.oldPosition then\n                    task.wait(0.2)\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild("HumanoidRootPart")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.upgradeSkill.oldPosition)\n                            NexusState.upgradeSkill.oldPosition = nil\n                            NexusState.upgradeSkill.teleported = false\n                        end\n                    end\n                end\n\n                if success then\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "Upgraded " .. selectedSkill .. "!", Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = "Upgrade Skill", Message = "Failed: " .. tostring(err), Duration = 2 })\n                end\n            end\n        })\n    end\n\n    -- Craft Rod\n    do\n        local CraftRodSection = ShopTab:CreateSection("Craft Rod")\n        local ROD_RECIPES = {\n            ["Heavenpiercer Rod"] = {\n                {name = "Flying Fish Emperor", minKg = 1000000, maxKg = 3000000},\n                {name = "Flying Fish Empress", minKg = 1000000, maxKg = 3000000},\n                {name = "Heavenpiercer Turtle", minKg = 3000000, maxKg = 6000000},\n                {name = "Rainbow Dragonfish", minKg = 5000000, maxKg = 8000000},\n            },\n            ["Pure Diamond Rod"] = {\n                {name = "Frost Kingfish", minKg = 4000000, maxKg = 7000000},\n                {name = "Frost Queenfish", minKg = 4000000, maxKg = 8000000},\n                {name = "Sanguine Fish", minKg = 3000000, maxKg = 6000000},\n                {name = "Draconic Koi", minKg = 1000000, maxKg = 3000000},\n            },\n            ["Sacred Bamboo Rod"] = {\n                {name = "Nameless Octoparasite", minKg = 6000000, maxKg = 9000000},\n                {name = "Reborn Puffer Beast", minKg = 4000000, maxKg = 6000000},\n                {name = "Ascended Perch", minKg = 900000, maxKg = 1000000},\n                {name = "Mountain Fish", minKg = 1000000, maxKg = 5000000},\n            }\n        }\n\n        local rodOptions = {"Heavenpiercer Rod", "Pure Diamond Rod", "Sacred Bamboo Rod"}\n        local selectedRod = rodOptions[1]\n\n        local rodDropdown = Cfg.register(CraftRodSection:CreateDropdown(Cfg.wrap("Dropdown", "Select Rod to Craft", {\n            Name = "Select Rod to Craft",\n            Options = rodOptions,\n            Default = selectedRod,\n            Callback = function(value) selectedRod = value end\n        })), "Dropdown", "Select Rod to Craft", {\n            Name = "Select Rod to Craft",\n            Options = rodOptions,\n            Default = selectedRod,\n            Callback = function(value) selectedRod = value end\n        })\n\n        Cfg.register(CraftRodSection:CreateDropdown(Cfg.wrap("Dropdown", "Craft Method", {\n            Name = "Craft Method",\n            Options = {"Instant", "Teleport"},\n            Default = "Instant",\n            Callback = function(value) NexusState.craftRodMethod = value end\n        })), "Dropdown", "Craft Method", {\n            Name = "Craft Method",\n            Options = {"Instant", "Teleport"},\n            Default = "Instant",\n            Callback = function(value) NexusState.craftRodMethod = value end\n        })\n\n        local function checkRodMaterials(rodName)\n            local recipe = ROD_RECIPES[rodName]\n            if not recipe then return false, "Recipe not found for " .. rodName end\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false, "Player data not found" end\n            local inventory = userData:FindFirstChild("Inventory")\n            if not inventory then return false, "Inventory not found" end\n            local fishCount = {}\n            for _, req in ipairs(recipe) do fishCount[req.name] = 0 end\n            for _, item in pairs(inventory:GetChildren()) do\n                local fishName, weight, count = parseCraftFishEntry(item)\n                if fishName and fishName ~= "" then\n                    local req = nil\n                    for _, r in ipairs(recipe) do\n                        if r.name == fishName then req = r; break end\n                    end\n                    if req then\n                        if weight and weight >= req.minKg and weight <= req.maxKg then\n                            fishCount[req.name] = fishCount[req.name] + count\n                        end\n                    end\n                end\n            end\n            local missing = {}\n            for _, req in ipairs(recipe) do\n                local count = fishCount[req.name] or 0\n                if count < 1 then\n                    table.insert(missing, req.name .. " (need 1, have " .. count .. ")")\n                end\n            end\n            if #missing > 0 then\n                return false, "Missing materials: " .. table.concat(missing, ", ")\n            end\n            return true, "All materials ready!"\n        end\n\n        local function craftRod()\n            local ok, msg = checkRodMaterials(selectedRod)\n            if not ok then\n                NexusLib:Notify({ Title = "Craft Rod", Message = msg, Duration = 4 })\n                return\n            end\n            local method = NexusState.craftRodMethod or "Instant"\n            local teleported = false\n            if method == "Teleport" then\n                local npc = Workspace:FindFirstChild("NPC")\n                if npc then\n                    local buyRod = npc:FindFirstChild("BuyFishingRod")\n                    if buyRod then\n                        local biaoDi = buyRod:FindFirstChild("Biao Di")\n                        if typeof(biaoDi) == "Instance" and biaoDi:IsA("Model") then\n                            local hrp = biaoDi:FindFirstChild("HumanoidRootPart")\n                            if hrp then\n                                local char = LocalPlayer.Character\n                                if char then\n                                    local root = char:FindFirstChild("HumanoidRootPart")\n                                    if root then\n                                        NexusState.lastCraftPosition = root.Position\n                                        root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                        teleported = true\n                                        task.wait(0.3)\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n            local success, err = pcall(function()\n                Events.CraftRod:FireServer(selectedRod)\n            end)\n            if success then\n                NexusLib:Notify({ Title = "Craft Rod", Message = "Crafted " .. selectedRod .. " successfully!", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = "Craft Rod", Message = "Failed: " .. tostring(err), Duration = 2 })\n            end\n            if teleported and NexusState.lastCraftPosition then\n                task.wait(0.3)\n                local char = LocalPlayer.Character\n                if char then\n                    local root = char:FindFirstChild("HumanoidRootPart")\n                    if root then\n                        root.CFrame = CFrame.new(NexusState.lastCraftPosition)\n                        NexusState.lastCraftPosition = nil\n                    end\n                end\n            end\n        end\n\n        CraftRodSection:CreateButton({ Name = "Craft rod now", Callback = craftRod })\n        local autoCraftRodToggle = Cfg.register(CraftRodSection:CreateToggle(Cfg.wrap("Toggle", "Auto craft selected rod", {\n            Name = "Auto craft selected rod",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoCraftRodRunning = value\n                if value then\n                    if NexusState.autoCraftRodThread then\n                        task.cancel(NexusState.autoCraftRodThread)\n                        NexusState.autoCraftRodThread = nil\n                    end\n                    NexusState.autoCraftRodThread = task.spawn(function()\n                        while NexusState.autoCraftRodRunning do\n                            pcall(craftRod)\n                            task.wait(5)\n                        end\n       RhyStart then pcall(function() runtimeEnv.NexusRhyStart:Disconnect() end) end\n        if runtimeEnv.NexusRhyStop then pcall(function() runtimeEnv.NexusRhyStop:Disconnect() end) end\n        if runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) end\n        if runtimeEnv.NexusNamelessBGM then pcall(function() runtimeEnv.NexusNamelessBGM:Disconnect() end) end\n        if runtimeEnv.NexusNamelessP2 then pcall(function() runtimeEnv.NexusNamelessP2:Disconnect() end) end\n\n        pcall(function()\n            local evStart = Events:FindFirstChild("RhythmStart")\n            if evStart then\n                runtimeEnv.NexusRhyStart = evStart.OnClientEvent:Connect(function(cfg)\n                    if not alive() then return end\n                    Rhy.Config = cfg\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    Rhy.Stats = { hit = 0, spam = 0 }\n                    Rhy.NextPress = {}\n                    if Rhy.Enabled then\n                        local hp = cfg and (cfg.FinalMaxHP or cfg.HPFinalPhase)\n                        NexusLib:Notify({\n                            Title = "Auto Nameless",\n                            Message = "Nameless started [" .. tostring(Rhy.Mode) .. "]" .. (hp and (" | HP " .. tostring(hp)) or ""),\n                            Duration = 3,\n                        })\n                        if Rhy.Mode == "Risk" then rhyStartRisk() end\n                    end\n                end)\n            end\n            local evStop = Events:FindFirstChild("RhythmStop")\n            if evStop then\n                runtimeEnv.NexusRhyStop = evStop.OnClientEvent:Connect(function()\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                end)\n            end\n        end)\n\n        -- Nameless remotes captured after kill (remote.txt): BossPhaseBGM(name, sound) + BossPhase2Setup().\n        -- Arm the minigame on either remote so Auto Nameless works even when RhythmStart is late/missing.\n        pcall(function()\n            local evBGM = Events:FindFirstChild("BossPhaseBGM")\n            if evBGM then\n                runtimeEnv.NexusNamelessBGM = evBGM.OnClientEvent:Connect(function(bossName, _sound)\n                    if not alive() then return end\n                    if bossName ~= nil and tostring(bossName) ~= "Nameless Octoparasite"\n                        and tostring(bossName) ~= "Black Tortoise Bloodline" then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = "Auto Nameless", Message = "Nameless boss signal [" .. tostring(Rhy.Mode) .. "]", Duration = 3 })\n                    end\n                end)\n            end\n            local evP2 = Events:FindFirstChild("BossPhase2Setup")\n            if evP2 then\n                runtimeEnv.NexusNamelessP2 = evP2.OnClientEvent:Connect(function()\n                    if not alive() then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = "Auto Nameless", Message = "Nameless phase 2 [" .. tostring(Rhy.Mode) .. "]", Duration = 3 })\n                    end\n                end)\n            end\n        end)\n\n\n        runtimeEnv.NexusRhyLoop = RunService.Heartbeat:Connect(function()\n            if not alive() or not Rhy.Enabled then return end\n            local now = tick()\n            Rhy.Active = rhyUiActive() or now < (Rhy.SignalUntil or 0)\n            if not Rhy.Active then return end\n            if Rhy.Mode == "Risk" then rhyStartRisk() end\n            rhyScan(now)\n        end)\n\n        local NamelessSection = FarmingTab:CreateSection("Auto Nameless Octoparasite")\n        NamelessSection:CreateButton({\n            Name = "Teleport to Nameless Octoparasite",\n            Callback = function() pcall(rhyTeleportToNameless) end\n        })\n        Cfg.register(NamelessSection:CreateToggle(Cfg.wrap("Toggle", "Auto Nameless", {\n            Name = "Auto Nameless",\n            Default = false,\n            Callback = function(value)\n                Rhy.Enabled = value\n                if value then\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Enabled [" .. tostring(Rhy.Mode) .. "]. Waiting for Nameless signal from server.", Duration = 3 })\n                    if Rhy.Active and Rhy.Mode == "Risk" then rhyStartRisk() end\n                else\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Disabled | hit " .. tostring(Rhy.Stats.hit) .. " | remote " .. tostring(Rhy.Stats.spam), Duration = 3 })\n                end\n            end\n        })), "Toggle", "Auto Nameless", {\n            Name = "Auto Nameless",\n            Default = false,\n            Callback = function(value)\n                Rhy.Enabled = value\n                if value then\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Enabled [" .. tostring(Rhy.Mode) .. "]. Waiting for Nameless signal from server.", Duration = 3 })\n                    if Rhy.Active and Rhy.Mode == "Risk" then rhyStartRisk() end\n                else\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Disabled | hit " .. tostring(Rhy.Stats.hit) .. " | remote " .. tostring(Rhy.Stats.spam), Duration = 3 })\n                end\n            end\n        })\n    -- ===== AUTO BLACK TORTOISE BLOODLINE =====\n    do\n        local TORTOISE_NAME = "Black Tortoise Bloodline"\n        local autoBossEnabled = {\n            Enzo = NexusState.AutoEnzoEnabled == true or Fishing.Flags.AutoFightEnzo == true,\n            ["Long Diaohai"] = NexusState.AutoLongDiaohaiEnabled == true\n                or Fishing.Flags.AutoLongDiaohai == true,\n            ["Black Tortoise Bloodline"] = false,\n        }\n        local autoBossThreads = {}\n\n        local function isAnyBossMinigameVisible()\n            local fishing = MainGui and MainGui:FindFirstChild("Fishing")\n            local bossBar = fishing and fishing:FindFirstChild("BossFightBar")\n            return bossBar ~= nil and bossBar.Visible == true\n        end\n\n        local function isNamedBossInFight(bossName)\n            local active = false\n            pcall(function()\n                local npc = Workspace:FindFirstChild("NPC")\n                local boss = npc and npc:FindFirstChild(bossName, true)\n                if boss and boss:GetAttribute("InFight") == true then active = true end\n            end)\n            return active or isAnyBossMinigameVisible()\n        end\n\n        local function refreshAutoBossSkillCheck()\n            local anyEnabled = autoBossEnabled.Enzo == true\n                or autoBossEnabled["Long Diaohai"] == true\n                or autoBossEnabled["Black Tortoise Bloodline"] == true\n            NexusState.AutoEnzoEnabled = autoBossEnabled.Enzo == true\n            NexusState.AutoLongDiaohaiEnabled = autoBossEnabled["Long Diaohai"] == true\n            NexusState.AutoBlackTortoiseEnabled = autoBossEnabled["Black Tortoise Bloodline"] == true\n            Fishing.Flags.AutoSkillCheck = anyEnabled\n        end\n\n        local function setAutoBoss(bossName, enabled)\n            enabled = enabled == true\n            autoBossEnabled[bossName] = enabled\n            refreshAutoBossSkillCheck()\n\n            local oldThread = autoBossThreads[bossName]\n            if oldThread then\n                pcall(task.cancel, oldThread)\n                autoBossThreads[bossName] = nil\n            end\n            if not enabled then return end\n            if not StartBossFight then\n                NexusLib:Notify({ Title = "Auto Boss", Message = "StartBossFight remote is unavailable.", Duration = 3 })\n                return\n            end\n\n            MiscFlags.AutoEquipRod = true\n            pcall(function()\n                local toggleHotbar = Events:FindFirstChild("ToggleHotbar")\n                if toggleHotbar and toggleHotbar:IsA("RemoteFunction") then\n                    toggleHotbar:InvokeServer("1", nil)\n                elseif toggleHotbar and toggleHotbar:IsA("RemoteEvent") then\n                    toggleHotbar:FireServer("1", nil)\n                end\n            end)\n\n            autoBossThreads[bossName] = task.spawn(function()\n                local lastRequest = 0\n                while alive() and autoBossEnabled[bossName] do\n                    if not isNamedBossInFight(bossName) and tick() - lastRequest >= 4.0 then\n                        local fightMode = "Normal"\n                        if bossName == "Long Diaohai" then\n                            fightMode = Fishing.Flags.LongDiaohaiFightMode or "Normal"\n                        elseif bossName == "Black Tortoise Bloodline" then\n                            fightMode = "Hard"\n                        else\n                            fightMode = Fishing.Flags.BossFightMode or "Normal"\n                        end\n                        local ok = pcall(function()\n                            StartBossFight:FireServer(bossName, fightMode)\n                        end)\n                        if ok then lastRequest = tick() end\n                        task.wait(4.0)\n                    else\n                        task.wait(0.35)\n                    end\n                end\n                autoBossThreads[bossName] = nil\n            end)\n        end\n\n        local tortoiseFullOn = false\n        local tortoiseMiniOn = false\n        local tortoiseThread = nil\n\n        local function findTortoiseModel()\n            local roots = {}\n            local ocean = Workspace:FindFirstChild("Ocean")\n            if ocean then\n                local boss = ocean:FindFirstChild("Boss")\n                if boss then table.insert(roots, boss) end\n                table.insert(roots, ocean)\n            end\n            local fishes = Workspace:FindFirstChild("Fishes")\n            if fishes then table.insert(roots, fishes) end\n            local npc = Workspace:FindFirstChild("NPC")\n            if npc then table.insert(roots, npc) end\n            table.insert(roots, Workspace)\n            for _, root in ipairs(roots) do\n                local ok, found = pcall(function()\n                    return root:FindFirstChild(TORTOISE_NAME, true)\n                end)\n                if ok and found then return found end\n            end\n            return nil\n        end\n\n        local function tortoisePivot(inst)\n            if not inst then return nil end\n            local ok, cf = pcall(function()\n                if inst:IsA("BasePart") then return inst.CFrame end\n                if inst:IsA("Model") then\n                    if inst.PrimaryPart then return inst.PrimaryPart.CFrame end\n                    return inst:GetPivot()\n                end\n                local part = inst:FindFirstChildWhichIsA("BasePart", true)\n                return part and part.CFrame or nil\n            end)\n            return (ok and cf) or nil\n        end\n\n        local function teleportToTortoise()\n            local model = findTortoiseModel()\n            if not model then return false, "not found" end\n            local cf = tortoisePivot(model)\n            if not cf then return false, "no pivot" end\n            local char = LocalPlayer.Character\n            local hrp = char and char:FindFirstChild("HumanoidRootPart")\n            if not hrp then return false, "no hrp" end\n            pcall(functi