"M\xC3\xCC\xD8\xB1\xFA\x80\xBC\xBE\x80\xCA\x11?\xDB\xAA\xDC\x03\x81lqZ\xC0p\xF7hc5&8pMabyt",'d or "Instant",\n            Callback = function(value) NexusState.buyRod.method = value end\n        })\n\n        RodSection:CreateButton({\n            Name = "Buy Selected Rod",\n            Callback = function()\n                if selectedRod == "No rod available" then\n                    NexusLib:Notify({ Title = "Buy Rod", Message = "No rod available to buy", Duration = 2 })\n                    return\n                end\n                NexusState.buyRod.teleported = false\n                NexusState.buyRod.oldPosition = nil\n                if NexusState.buyRod.method == "Teleport" then\n                    local npc = Workspace:FindFirstChild("NPC")\n                    if npc then\n                        local buyFishingRod = npc:FindFirstChild("BuyFishingRod")\n                        if buyFishingRod then\n                            local biaoDi = buyFishingRod:FindFirstChild("Biao Di")\n                            if typeof(biaoDi) == "Instance" and biaoDi:IsA("Model") then\n                                local hrp = biaoDi:FindFirstChild("HumanoidRootPart")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            NexusState.buyRod.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.buyRod.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.buyRod.teleported then\n                        NexusLib:Notify({ Title = "Buy Rod", Message = "Could not find Biao Di, teleport failed. Continuing anyway.", Duration = 3 })\n                    end\n                end\n                pcall(function()\n                    Events.BuyFishingRod:FireServer(selectedRod)\n                    NexusLib:Notify({ Title = "Buy Rod", Message = "Bought " .. selectedRod, Duration = 2 })\n                end)\n                if NexusState.buyRod.teleported and NexusState.buyRod.oldPosition then\n                    task.wait(0.2)\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild("HumanoidRootPart")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.buyRod.oldPosition)\n                            NexusState.buyRod.oldPosition = nil\n                            NexusState.buyRod.teleported = false\n                        end\n                    end\n                end\n            end\n        })\n    end\n\n    -- Learn Skills\n    do\n        local LearnSection = ShopTab:CreateSection("Learn Skills")\n        local function GetLearnableSkills()\n            local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not p then return {"No skill available"} end\n            local skills = {}\n            for _, skillFolder in pairs(p.Skill:GetChildren()) do\n                if typeof(skillFolder) == "Instance" and typeof(skillFolder) == "Instance" and skillFolder:IsA("Folder") then\n                    local owned = skillFolder:FindFirstChild("Owned")\n                    if owned and owned.Value == false then\n                        local mod = Info and Info.Skill and Info.Skill:FindFirstChild(skillFolder.Name)\n                        if mod then\n                            local ok, m = pcall(require, mod)\n                            if ok and m and m.Price and m.Price > 0 then\n                                table.insert(skills, skillFolder.Name)\n                            end\n                        end\n                    end\n                end\n            end\n            if #skills == 0 then return {"No skill available"} end\n            return skills\n        end\n\n        local learnableSkills = GetLearnableSkills()\n        local selectedLearnSkills = {}\n\n        local learnDropdown = Cfg.register(LearnSection:CreateMultiDropdown(Cfg.wrap("MultiDropdown", "Select Skills to Learn", {\n            Name = "Select Skills to Learn",\n            Options = learnableSkills,\n            Default = {},\n            Callback = function(values) selectedLearnSkills = values end\n        })), "MultiDropdown", "Select Skills to Learn", {\n            Name = "Select Skills to Learn",\n            Options = learnableSkills,\n            Default = {},\n            Callback = function(values) selectedLearnSkills = values end\n        })\n\n        local learnMethodDropdown = Cfg.register(LearnSection:CreateDropdown(Cfg.wrap("Dropdown", "Learn Method", {\n            Name = "Learn Method",\n            Options = {"Instant", "Teleport"},\n            Default = NexusState.learnSkill.method or "Instant",\n            Callback = function(value) NexusState.learnSkill.method = value end\n        })), "Dropdown", "Learn Method", {\n            Name = "Learn Method",\n            Options = {"Instant", "Teleport"},\n            Default = NexusState.learnSkill.method or "Instant",\n            Callback = function(value) NexusState.learnSkill.method = value end\n        })\n\n        LearnSection:CreateButton({\n            Name = "Learn Selected Skills",\n            Callback = function()\n                if #selectedLearnSkills == 0 then\n                    NexusLib:Notify({ Title = "Learn Skills", Message = "No skills selected", Duration = 2 })\n                    return\n                end\n                NexusState.learnSkill.teleported = false\n                NexusState.learnSkill.oldPosition = nil\n                if NexusState.learnSkill.method == "Teleport" then\n                    local npc = Workspace:FindFirstChild("NPC")\n                    if npc then\n                        local learnSkill = npc:FindFirstChild("LearnSkill")\n                        if learnSkill then\n                            local sageYijiu = learnSkill:FindFirstChild("Sage Yijiu")\n                            if typeof(sageYijiu) == "Instance" and sageYijiu:IsA("Model") then\n                                local hrp = sageYijiu:FindFirstChild("HumanoidRootPart")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild("HumanoidRootPart")\n                                        if root then\n                                            NexusState.learnSkill.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.learnSkill.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.learnSkill.teleported then\n                        NexusLib:Notify({ Title = "Learn Skills", Message = "Could not find Sage Yijiu, teleport failed. Continuing anyway.", Duration = 3 })\n                    end\n                end\n                local learnedCount = 0\n                for _, skillName in ipairs(selectedLearnSkills) do\n                    local success, err = pcall(function()\n                        Events.BuySkill:FireServer(skillName)\n                    end)\n                    if success then\n                        learnedCount = learnedCount + 1\n                        NexusLib:Notify({ Title = "Learn Skills", Message = "Learned " .. skillName, Duration = 2 })\n                    else\n                        NexusLib:Notify({ Title = "Learn Skills", Message = "Failed to learn " .. skillName .. ": " .. tostring(err), Duration = 2 })\n                    end\n                    task.wait(0.3)\n                end\n                if NexusState.learnSkill.teleported and NexusState.learnSkill.oldPosition then\n                    task.wait(0.2)\n                    local char = LocalPlayer.Character\n                    if char then\n                        local root = char:FindFirstChild("HumanoidRootPart")\n                        if root then\n                            root.CFrame = CFrame.new(NexusState.learnSkill.oldPosition)\n                            NexusState.learnSkill.oldPosition = nil\n                            NexusState.learnSkill.teleported = false\n                        end\n                    end\n                end\n                NexusLib:Notify({ Title = "Learn Skills", Message = "Learned " .. learnedCount .. " skill(s)!", Duration = 3 })\n            end\n        })\n    end\n\n    -- Trait Reroll\n    do\n        local TraitSection = ShopTab:CreateSection("Trait Reroll")\n        local function GetOwnedSkillNames()\n            local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not p then return {"No skill owned"} end\n            local skills = {}\n            for _, f in pairs(p.Skill:GetChildren()) do\n                if typeof(f) == "Instance" and typeof(f) == "Instance" and f:IsA("Folder") and f.Owned and f.Owned.Value == true then\n                    table.insert(skills, f.Name)\n                end\n            end\n            if #skills == 0 then return {"No skill owned"} end\n            return skills\n        end\n\n        local function GetTraitNames()\n            local traits = {}\n            if not Info or not Info:FindFirstChild("Trait") then return {"No trait available"} end\n            for _, child in pairs(Info.Trait:GetChildren()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("ModuleScript") then\n                    local ok, mod = pcall(require, child)\n                    if ok and type(mod) == "table" and mod.Name then\n                        table.insert(traits, mod.Name)\n                    end\n                end\n            end\n            if #traits == 0 then return {"No trait available"} end\n            return traits\n        end\n\n        local ownedSkills = GetOwnedSkillNames()\n        local selectedSkillForReroll = ownedSkills[1] or "No skill owned"\n        local traitNames = GetTraitNames()\n        local selectedTargetTrait = traitNames[1] or "No trait available"\n        local ignoreLocked = false\n\n        local traitSkillDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap("Dropdown", "Select Skill", {\n            Name = "Select Skill",\n            Options = ownedSkills,\n            Default = selectedSkillForReroll,\n            Callback = function(value) selectedSkillForReroll = value end\n        })), "Dropdown", "Select Skill", {\n            Name = "Select Skill",\n            Options = ownedSkills,\n            Default = selectedSkillForReroll,\n            Callback = function(value) selectedSkillForReroll = value end\n        })\n\n        local targetTraitDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap("Dropdown", "Target Trait", {\n            Name = "Target Trait",\n            Options = traitNames,\n            Default = selectedTargetTrait,\n            Callback = function(value) selectedTargetTrait = value end\n        })), "Dropdown", "Target Trait", {\n            Name = "Target Trait",\n            Options = traitNamesarent is a Folder\n                if not godModel.Parent or typeof(godModel.Parent) ~= "Instance" or not godModel.Parent:IsA("Folder") then return end\n                \n                local attachPart = godModel:FindFirstChildWhichIsA("BasePart")\n                if not attachPart then\n                    attachPart = godModel:FindFirstChildWhichIsA("BasePart", true)\n                end\n                if not attachPart then return end\n                \n                local highlight = Instance.new("Highlight")\n                highlight.FillColor = Color3.fromRGB(255, 215, 0)\n                highlight.FillTransparency = 0.4\n                highlight.OutlineColor = Color3.fromRGB(255, 255, 100)\n                highlight.OutlineTransparency = 0.2\n                highlight.Adornee = godModel\n                highlight.Parent = godModel\n                \n                local billboard = Instance.new("BillboardGui")\n                billboard.Name = "GodEspBillboard"\n                billboard.Size = UDim2.new(0, 200, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2.5, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new("Frame")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new("UICorner")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new("TextLabel")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(255, 215, 0)\n                label.Text = "\u{2600}\u{FE0F} " .. godModel.Name\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                godEspHighlights[godModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeGodEsp(godModel)\n                local data = godEspHighlights[godModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    godEspHighlights[godModel] = nil\n                end\n            end\n            \n            local function clearAllGodEsp()\n                for model, data in pairs(godEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                godEspHighlights = {}\n            end\n            \n            local function scanAllGods()\n                if not godFolder then return end\n                for _, child in ipairs(godFolder:GetDescendants()) do\n                    if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                        if not godEspHighlights[child] then\n                            pcall(function() createGodEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startGodEsp()\n                if godEspEnabled then return end\n                godEspEnabled = true\n                scanAllGods()\n                \n                if godFolder then\n                    local godAddedConn = godFolder.DescendantAdded:Connect(function(desc)\n                        if godEspEnabled and typeof(desc) == "Instance" and desc:IsA("Model") and desc.Parent and typeof(desc.Parent) == "Instance" and desc.Parent:IsA("Folder") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not godEspHighlights[desc] then\n                                    createGodEsp(desc)\n                                end\n                            end)\n                        end\n                    end)\n                    table.insert(espConnections, { conn = godAddedConn })\n                end\n                \n                godEspThread = task.spawn(function()\n                    while godEspEnabled do\n                        task.wait(10)\n                        if godEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(godEspHighlights) do\n                                    if not model.Parent then\n                                        removeGodEsp(model)\n                                    end\n                                end\n                                scanAllGods()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = "God ESP", Message = "God ESP enabled!", Duration = 2 })\n            end\n            \n            local function stopGodEsp()\n                godEspEnabled = false\n                if godEspThread then\n                    task.cancel(godEspThread)\n                    godEspThread = nil\n                end\n                clearAllGodEsp()\n                NexusLib:Notify({ Title = "God ESP", Message = "God ESP disabled!", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap("Toggle", "God ESP", {\n                Name = "God ESP",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startGodEsp()\n                    else\n                        stopGodEsp()\n                    end\n                end\n            })), "Toggle", "God ESP", {\n                Name = "God ESP",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startGodEsp()\n                    else\n                        stopGodEsp()\n                    end\n                end\n            })\n        end\n        \n        -- ===== NPCs ESP =====\n        do\n            local npcEspEnabled = false\n            local npcEspThread = nil\n            local npcEspHighlights = {}\n            local npcFolder = workspace:FindFirstChild("NPC") and workspace.NPC:FindFirstChild("Function")\n            \n            local function createNpcEsp(npcModel)\n                if not npcModel or typeof(npcModel) ~= "Instance" or not npcModel:IsA("Model") then return end\n                if npcEspHighlights[npcModel] then return end\n                \n                if not npcModel.Parent or typeof(npcModel.Parent) ~= "Instance" or not npcModel.Parent:IsA("Folder") then return end\n                \n                local attachPart = npcModel:FindFirstChildWhichIsA("BasePart")\n                if not attachPart then\n                    attachPart = npcModel:FindFirstChildWhichIsA("BasePart", true)\n                end\n                if not attachPart then return end\n                \n                local highlight = Instance.new("Highlight")\n                highlight.FillColor = Color3.fromRGB(255, 100, 0)\n                highlight.FillTransparency = 0.4\n                highlight.OutlineColor = Color3.fromRGB(255, 200, 50)\n                highlight.OutlineTransparency = 0.2\n                highlight.Adornee = npcModel\n                highlight.Parent = npcModel\n                \n                local billboard = Instance.new("BillboardGui")\n                billboard.Name = "NpcEspBillboard"\n                billboard.Size = UDim2.new(0, 200, 0, 30)\n                billboard.StudsOffset = Vector3.new(0, 2.5, 0)\n                billboard.AlwaysOnTop = true\n                billboard.Parent = attachPart\n                \n                local frame = Instance.new("Frame")\n                frame.Size = UDim2.new(1, 0, 1, 0)\n                frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)\n                frame.BackgroundTransparency = 0.5\n                frame.BorderSizePixel = 0\n                frame.Parent = billboard\n                \n                local corner = Instance.new("UICorner")\n                corner.CornerRadius = UDim.new(0, 4)\n                corner.Parent = frame\n                \n                local label = Instance.new("TextLabel")\n                label.Size = UDim2.new(1, 0, 1, 0)\n                label.BackgroundTransparency = 1\n                label.Font = Enum.Font.GothamBold\n                label.TextSize = 14\n                label.TextColor3 = Color3.fromRGB(255, 150, 50)\n                label.Text = "NPC | " .. npcModel.Name\n                label.TextScaled = false\n                label.TextXAlignment = Enum.TextXAlignment.Center\n                label.TextYAlignment = Enum.TextYAlignment.Center\n                label.Parent = frame\n                \n                npcEspHighlights[npcModel] = {\n                    highlight = highlight,\n                    billboard = billboard,\n                    attachPart = attachPart,\n                }\n            end\n            \n            local function removeNpcEsp(npcModel)\n                local data = npcEspHighlights[npcModel]\n                if data then\n                    if data.highlight then data.highlight:Destroy() end\n                    if data.billboard then data.billboard:Destroy() end\n                    npcEspHighlights[npcModel] = nil\n                end\n            end\n            \n            local function clearAllNpcEsp()\n                for model, data in pairs(npcEspHighlights) do\n                    pcall(function()\n                        if data.highlight then data.highlight:Destroy() end\n                        if data.billboard then data.billboard:Destroy() end\n                    end)\n                end\n                npcEspHighlights = {}\n            end\n            \n            local function scanAllNpcs()\n                if not npcFolder then return end\n                for _, child in ipairs(npcFolder:GetDescendants()) do\n                    if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                        if not npcEspHighlights[child] then\n                            pcall(function() createNpcEsp(child) end)\n                        end\n                    end\n                end\n            end\n            \n            local function startNpcEsp()\n                if npcEspEnabled then return end\n                npcEspEnabled = true\n                scanAllNpcs()\n                \n                if npcFolder then\n                    local npcAddedConn = npcFolder.DescendantAdded:Connect(function(desc)\n                        if npcEspEnabled and typeof(desc) == "Instance" and desc:IsA("Model") and desc.Parent and typeof(desc.Parent) == "Instance" and desc.Parent:IsA("Folder") then\n                            task.wait(0.1)\n                            pcall(function()\n                                if not npcEspHighlights[desc] then\n                                    createNpcEsp(desc)\n                           then\n                islandOk = false\n            end\n        end\n        if islandOk and (island.power or 0) <= currentPower then\n            table.insert(eligible, island)\n        end\n    end\n    table.sort(eligible, function(a, b) return a.power > b.power end)\n    NexusState.cachedRecommended = eligible[2] or eligible[1]\n    NexusState.cachedRecommendedAt = _rcNow\n    return NexusState.cachedRecommended\nend\n\nlocal function isHoldingFishingRod()\n    local char = LocalPlayer.Character\n    if not char then return false end\n    local typ = char:GetAttribute("Type")\n    if typ and string.lower(tostring(typ)) == "fishing rod" then return true end\n    return false\nend\n\n-- ============================================================\n\n-- ============================================================\n-- ===== CONFIG SYSTEM (save / load / auto-load / import-export) =====\n-- ============================================================\n-- Every Toggle / Dropdown / MultiDropdown / Textbox with a static English Name is\n-- registered here through Cfg.wrap(kind, name, config) at creation time. The config\n-- table itself is untouched (defaults still come from Default = ...), the registry\n-- only keeps the live handle so save/load can Get/Set values later.\n--\n-- Save format is a flat { [controlName] = value } table, JSON-encoded. Control\n-- names are unique across the whole hub (verified), so no tab/section prefix is\n-- needed and configs stay compatible even if a control moves sections.\ndo\n    local ConfigSys = {}\n    ConfigSys.registry = {}   -- [name] = { kind = "toggle"|"dropdown"|"multi"|"text", get = fn, set = fn }\n    ConfigSys.ordered = {}    -- registration order, for stable exports\n    ConfigSys.FILE = "NexusHub_Config.json"\n    ConfigSys.AUTO_FILE = "NexusHub_AutoLoad.json"\n    ConfigSys._saving = false\n\n    local function cfgKind(callKind)\n        if callKind == "Toggle" then return "toggle" end\n        if callKind == "Dropdown" then return "dropdown" end\n        if callKind == "MultiDropdown" then return "multi" end\n        return "text"\n    end\n\n    -- Wrap a control config table: pass through untouched, remember the name so\n    -- the returned handle can be registered right after creation.\n    function ConfigSys.wrap(callKind, name, config)\n        config = config or {}\n        config._CfgKind = callKind\n        config._CfgName = name\n        return config\n    end\n\n    function ConfigSys.register(handle, callKind, name, config)\n        if not handle or not name then return handle end\n        local kind = cfgKind(callKind)\n        local entry = ConfigSys.registry[name]\n        if not entry then\n            entry = { kind = kind }\n            ConfigSys.registry[name] = entry\n            table.insert(ConfigSys.ordered, name)\n        end\n        entry.kind = kind\n        -- The original Callback is captured here at registration time (from the\n        -- config table), because NexusLib handles do not expose it.\n        local cb = config and config.Callback or nil\n        if type(handle.Get) == "function" then\n            entry.get = function()\n                local ok, v = pcall(handle.Get)\n                return ok and v or nil\n            end\n        end\n        -- NOTE: NexusLib Set() implementations do NOT fire Callback (toggle Set\n        -- calls set(v, false); dropdown/text Set only touch the label). After\n        -- Set we therefore re-fire the captured Callback so the hub state\n        -- (Fishing.Flags, NexusState, ...) actually follows the loaded value.\n        if type(handle.Set) == "function" then\n            entry.set = function(v)\n                pcall(handle.Set, handle, v)\n                if cb then\n                    task.spawn(cb, v)\n                end\n            end\n        elseif cb then\n            entry.set = function(v)\n                task.spawn(cb, v)\n            end\n        end\n        return handle\n    end\n\n    function ConfigSys.snapshot()\n        local out = {}\n        for name, entry in pairs(ConfigSys.registry) do\n            if entry.get then\n                local ok, v = pcall(entry.get)\n                if ok and v ~= nil then out[name] = v end\n            end\n        end\n        return out\n    end\n\n    function ConfigSys.apply(data)\n        if type(data) ~= "table" then return 0, 0 end\n        local okCount, missCount = 0, 0\n        for name, value in pairs(data) do\n            local entry = ConfigSys.registry[name]\n            if entry and entry.set then\n                local ok = pcall(entry.set, value)\n                if ok then okCount = okCount + 1 else missCount = missCount + 1 end\n            else\n                missCount = missCount + 1\n            end\n        end\n        return okCount, missCount\n    end\n\n    local function encode(data)\n        local HttpService = Services.HttpService\n        local ok, s = pcall(HttpService.JSONEncode, HttpService, data)\n        return ok and s or nil\n    end\n\n    local function decode(s)\n        local HttpService = Services.HttpService\n        local ok, data = pcall(HttpService.JSONDecode, HttpService, s)\n        if ok and type(data) == "table" then return data end\n        return nil\n    end\n\n    function ConfigSys.save(slot)\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then\n            NexusLib:Notify({ Title = "Config", Message = "Encode failed.", Duration = 3 })\n            return false\n        end\n        if not writefile then\n            NexusLib:Notify({ Title = "Config", Message = "This executor cannot save files.", Duration = 3 })\n            return false\n        end\n        local ok = pcall(writefile, slot or ConfigSys.FILE, payload)\n        NexusLib:Notify({ Title = "Config", Message = ok and "Saved." or "Save failed.", Duration = 2 })\n        return ok\n    end\n\n    function ConfigSys.load(slot, silent)\n        if not (isfile and readfile) then\n            if not silent then NexusLib:Notify({ Title = "Config", Message = "This executor cannot read files.", Duration = 3 }) end\n            return false\n        end\n        local path = slot or ConfigSys.FILE\n        local has = false\n        pcall(function() has = isfile(path) end)\n        if not has then\n            if not silent then NexusLib:Notify({ Title = "Config", Message = "No saved config found.", Duration = 3 }) end\n            return false\n        end\n        local ok, raw = pcall(readfile, path)\n        if not ok or not raw then\n            if not silent then NexusLib:Notify({ Title = "Config", Message = "Read failed.", Duration = 3 }) end\n            return false\n        end\n        local wrap = decode(raw)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            if not silent then NexusLib:Notify({ Title = "Config", Message = "Config file is corrupt.", Duration = 3 }) end\n            return false\n        end\n        -- Defer one frame so every tab has finished building its controls.\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            if not silent then\n                NexusLib:Notify({ Title = "Config", Message = "Loaded " .. okCount .. " settings" .. (missCount > 0 and " (" .. missCount .. " skipped)" or "") .. ".", Duration = 3 })\n            end\n        end)\n        return true\n    end\n\n    function ConfigSys.exportCode()\n        local payload = encode({ version = 1, savedAt = os.time(), data = ConfigSys.snapshot() })\n        if not payload then return nil end\n        local clip = (syn and syn.write_clipboard) or setclipboard or toclipboard\n        if clip then\n            pcall(clip, payload)\n            NexusLib:Notify({ Title = "Config", Message = "Config code copied to clipboard.", Duration = 3 })\n        else\n            NexusLib:Notify({ Title = "Config", Message = "Clipboard not supported on this executor.", Duration = 3 })\n        end\n        return payload\n    end\n\n    -- Import reads the clipboard when the executor exposes it; otherwise it falls\n    -- back to the textbox value typed/pasted by the user.\n    function ConfigSys.importCode(text)\n        local code = text\n        if (not code or code == "") and getclipboard then\n            pcall(function() code = getclipboard() end)\n        end\n        if not code or code == "" then\n            NexusLib:Notify({ Title = "Config", Message = "Paste a config code first.", Duration = 3 })\n            return false\n        end\n        local wrap = decode(code)\n        local data = wrap and (wrap.data or wrap) or nil\n        if not data then\n            NexusLib:Notify({ Title = "Config", Message = "Invalid config code.", Duration = 3 })\n            return false\n        end\n        task.defer(function()\n            local okCount, missCount = ConfigSys.apply(data)\n            NexusLib:Notify({ Title = "Config", Message = "Imported " .. okCount .. " settings" .. (missCount > 0 and " (" .. missCount .. " skipped)" or "") .. ".", Duration = 3 })\n        end)\n        return true\n    end\n\n    runtimeEnv.NexusConfig = ConfigSys\n    runtimeEnv.NexusCfgWrap = ConfigSys.wrap\n    ConfigSys._saving = false\nend\n\n\nlocal Cfg = runtimeEnv.NexusConfig\n\n-- ===== HOME TAB =====\n-- ============================================================\ndo\n    runtimeEnv.NexusStage("dung UI: Session tab")\n    local HomeTab\n    do\n        runtimeEnv.NexusStage("dung UI: Session tab")\n        local ok, result = pcall(function() return Window:CreateTab("Session") end)\n        if not ok or result == nil then\n            runtimeEnv.NexusStage("UI Session tab failed")\n            runtimeEnv.NexusReport("Nexus UI failed", "CreateTab Session: " .. tostring(result))\n            return\n        end\n        HomeTab = result\n    end\n    HomeTab:CreateHeader({\n        Title = "Session overview",\n        Subtitle = "Live instruments for " .. LocalPlayer.Name\n    })\n    local statRow = HomeTab:CreateStatRow({\n        {Title = "LEVEL", Value = "...", Color = Color3.fromRGB(190, 158, 103)},\n        {Title = "BALANCE", Value = "...", Color = Color3.fromRGB(128, 159, 164)},\n        {Title = "SESSION", Value = "00:00:00", Color = Color3.fromRGB(139, 161, 142)}\n    })\n        -- Add 9 new stats\n    local statRow2 = HomeTab:CreateStatRow({\n        {Title = "ROD", Value = "...", Color = Color3.fromRGB(255, 215, 0)},\n        {Title = "CRYSTAL", Value = "...", Color = Color3.fromRGB(100, 200, 255)},\n        {Title = "ESSENCE", Value = "...", Color = Color3.fromRGB(255, 100, 200)}\n    })\n    local statRow3 = HomeTab:CreateStatRow({\n        {Title = "BAIT", Value = "...", Color = Color3.fromRGB(150, 255, 150)},\n        {Title = "FISH CAUGHT", Value = "...", Color = Color3.fromRGB(255, 200, 100)},\n        {Title = "TICKET", Value = "...", Color = Color3.fromRGB(200, 150, 255)}\n    })\n    local statRow4 = HomeTab:CreateStatRow({\n        {Title = "TRAIT REROLL", Value = "...", Color = Color3.fromRGB(255, 150, 150)},\n        {Title = "HEAVIEST FISH", Value = "...", Color = Color3.fromRGB(255, 180, 50)},\n        {Title = "BASE HP", Value = "...", Color = Color3.fromRGB(255, 100, 100)}\n    })\n    local hwid = "N/A"\n    pcall(function() hwid = Services.RbxAnalyticsService:GetClientId() end)\n    HomeTab:CreateFeaturedCard({\n        Tag = "Nexus",\n        Title = "Heavyweight Fishing",\n        Description = "Script by: Ngmankhoi,NgdepZaiNhatTG,Ethangcuto\\n\\nHWID: " .. string.sub(hwid, 1, 15) .. "...",\n        ButtonText = "DISCORD",\n        Callback = function()\n            NexusLib:Notify({ Title = "Discord", Message = "Link copied to clipboard!", Duration = 3 })\n            if setclipboard then setclipboard("https://discord.gg/QAdVUX2wCH") end\n        end\n    })\n\n        local scriptStartTime = time()\ntude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n            if not bestHRP then\n                for _, desc in ipairs(npcFolder:GetDescendants()) do\n                    if typeof(desc) == "Instance" and typeof(desc) == "Instance" and desc:IsA("Model") and string.find(desc.Name:lower(), "bait") then\n                        local hrp = desc:FindFirstChild("HumanoidRootPart") or desc:FindFirstChild("Torso") or desc.PrimaryPart\n                        if hrp then\n                            local dist = (hrp.Position - myPos).Magnitude\n                            if dist < bestDist then\n                                bestDist = dist\n                                bestHRP = hrp\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end)\n    return bestHRP\nend\n\n-- ============================================================\n-- ===== AUTO FARM HELPERS =====\n-- ============================================================\n\n-- Check whether Auto Farm Boss is enabled\nlocal function bossFarmEnabled()\n    return NexusState.Fishing.Flags.AutoFarmBoss or NexusState.Fishing.Flags.AutoFarmSecretBoss\nend\n\n-- Reset Boss Farm state\nlocal function resetBossFarmTarget()\n    NexusState.Fishing.BossFarm.CurrentTarget = nil\n    NexusState.Fishing.BossFarm.CurrentType = nil\n    NexusState.Fishing.BossFarm.CurrentToken = nil\n    NexusState.Fishing.BossFarm.HasHooked = false\n    NexusState.Fishing.BossFarm.PendingCancel = false\nend\n\n-- Read info about the target currently biting\nlocal function getCurrentHookTarget()\n    local target = NexusState.Fishing.BossFarm.CurrentTarget\n    local info = { Name = nil, Data = nil, Instance = nil, Boss = false, SecretBoss = false }\n\n    if type(target) == "table" then\n        info.Data = target\n        info.Name = target.FishName or target.Name or target.fishName\n        info.Boss = target.Boss == true or target.SpecialBoss == true or target.SecretBoss == true\n        info.SecretBoss = target.SecretBoss == true\n    elseif typeof and typeof(target) == "Instance" then\n        info.Instance = target\n        info.Name = target:GetAttribute("FishName") or target.Name\n        info.Boss = target:GetAttribute("Boss") == true or target:GetAttribute("SpecialBoss") == true or target:GetAttribute("SecretBoss") == true\n        info.SecretBoss = target:GetAttribute("SecretBoss") == true\n    elseif type(target) == "string" then\n        info.Name = target\n    end\n\n    local fishId = LocalPlayer:GetAttribute("FishID")\n    local fishes = Workspace:FindFirstChild("Fishes")\n    local fishInstance = fishId and fishes and fishes:FindFirstChild(tostring(fishId))\n\n    if fishInstance then\n        info.Instance = fishInstance\n        info.Name = info.Name or fishInstance:GetAttribute("FishName") or fishInstance.Name\n        info.Boss = info.Boss or fishInstance:GetAttribute("Boss") == true or fishInstance:GetAttribute("SpecialBoss") == true or fishInstance:GetAttribute("SecretBoss") == true\n        info.SecretBoss = info.SecretBoss or fishInstance:GetAttribute("SecretBoss") == true\n    end\n\n    local fishingGui = MainGui:FindFirstChild("Fishing")\n    local progression = fishingGui and fishingGui:FindFirstChild("ProgressionBar")\n    local fishNameLabel = progression and progression:FindFirstChild("FishName")\n\n    if (not info.Name or info.Name == "" or info.Name == "???") and fishNameLabel and fishNameLabel.Text ~= "" then\n        info.Name = fishNameLabel.Text\n    end\n\n    return info\nend\n\nlocal function textHasKeyword(text, keywords)\n    text = string.lower(tostring(text or ""))\n    for _, keyword in ipairs(keywords) do\n        if string.find(text, keyword, 1, true) then return true end\n    end\n    return false\nend\n\n-- Check whether the target is a Secret Boss\nlocal function isSecretBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    local name = string.lower(tostring(current.Name or ""))\n    return current.SecretBoss or NexusState.SecretBossNameSet[name] or textHasKeyword(name, NexusState.SecretBossKeywords)\nend\n\n-- Check whether the target is a Boss\nlocal function isBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    local name = string.lower(tostring(current.Name or ""))\n    if isSecretBossTarget(current) then return true end\n    return current.Boss or NexusState.BossNameSet[name] or textHasKeyword(name, NexusState.BossKeywords)\nend\n\n-- Decide whether this target should be farmed\nlocal function shouldFarmBossTarget(target)\n    local current = target or getCurrentHookTarget()\n    if isSecretBossTarget(current) then return true, "Secret Boss" end\n    if NexusState.Fishing.Flags.AutoFarmSecretBoss and not NexusState.Fishing.Flags.AutoFarmBoss then return false, "Normal" end\n    if NexusState.Fishing.Flags.AutoFarmBoss and isBossTarget(current) then return true, "Boss" end\n    return false, "Normal"\nend\n\n-- Cancel the cast or release a common fish\nlocal function cancelOrReleaseNormalFish()\n    if not bossFarmEnabled() then return false end\n    local character = LocalPlayer.Character\n    if not character then return false end\n    if not character:GetAttribute("Fishing") then resetBossFarmTarget(); return true end\n\n    NexusState.Fishing.BossFarm.PendingCancel = true\n\n    pcall(function()\n        local fishingGui = MainGui:FindFirstChild("Fishing")\n        local barFrame = fishingGui and fishingGui:FindFirstChild("BarFrame")\n        local bar = barFrame and barFrame:FindFirstChild("Bar")\n        if bar then bar.Position = UDim2.new(-0.15, 0, bar.Position.Y.Scale, bar.Position.Y.Offset) end\n    end)\n\n    if NexusState.Fishing.BossFarm.CurrentToken and tick() - NexusState.Fishing.BossFarm.LastFastCancel > 0.5 then\n        NexusState.Fishing.BossFarm.LastFastCancel = tick()\n        pcall(function() Events.FishingMinigame:FireServer(false, NexusState.Fishing.BossFarm.CurrentToken) end)\n    end\n\n    if not character:GetAttribute("Retractable") then return false end\n    if tick() - NexusState.Fishing.BossFarm.LastCancel < 0.35 then return false end\n\n    NexusState.Fishing.BossFarm.LastCancel = tick()\n    pcall(function()\n        local root = character:FindFirstChild("HumanoidRootPart")\n        if root then Events.Fishing:FireServer(root.CFrame) end\n    end)\n\n    return false\nend\n\n-- textHasKeyword helper (if not defined yet)\nif not textHasKeyword then\n    local function textHasKeyword(text, keywords)\n        text = string.lower(tostring(text or ""))\n        for _, keyword in ipairs(keywords) do\n            if string.find(text, keyword, 1, true) then return true end\n        end\n        return false\n    end\nend\n\nlocal function loadBossNameSets()\n    for k in pairs(NexusState.BossNameSet) do NexusState.BossNameSet[k] = nil end\n    for k in pairs(NexusState.SecretBossNameSet) do NexusState.SecretBossNameSet[k] = nil end\n    local infoFolder = ReplicatedStorage:FindFirstChild("Info")\n    if not infoFolder then return end\n\n    pcall(function()\n        local areaRarity = infoFolder:FindFirstChild("FishingAreaRarity")\n        if areaRarity then\n            local rarityData = require(areaRarity)\n            if type(rarityData) == "table" and type(rarityData["Secret Boss"]) == "table" then\n                for fishName in pairs(rarityData["Secret Boss"]) do\n                    local name = string.lower(tostring(fishName))\n                    NexusState.SecretBossNameSet[name] = true\n                    NexusState.BossNameSet[name] = true\n                end\n            end\n        end\n    end)\n\n    pcall(function()\n        local inventory = infoFolder:FindFirstChild("Inventory")\n        if inventory then\n            for _, module in pairs(inventory:GetChildren()) do\n                if typeof(module) == "Instance" and typeof(module) == "Instance" and module:IsA("ModuleScript") then\n                    local ok, itemData = pcall(require, module)\n                    if ok and type(itemData) == "table" then\n                        local name = string.lower(tostring(itemData.FishName or module.Name))\n                        if itemData.Boss == true or itemData.SpecialBoss == true or itemData.SecretBoss == true then\n                            NexusState.BossNameSet[name] = true\n                        end\n                        if itemData.SecretBoss == true then\n                            NexusState.SecretBossNameSet[name] = true\n                        end\n                    end\n                end\n            end\n        end\n    end)\nend\n-- Defer heavy boss-name scan until after boot so opening the hub stays smooth\ntask.spawn(function()\n    task.wait(3)\n    if not alive() then return end\n    pcall(loadBossNameSets)\nend)\n\n-- ===== BUILD MAIN UI =====\nruntimeEnv.NexusStage("dung UI")\nlocal Window\ndo\n    local ok, result = pcall(function()\n        return NexusLib:CreateWindow({\n            Title = "NEXUS",\n            Subtitle = "HEAVYWEIGHT FISHING - LIVE SESSION",\n            Keybind = Enum.KeyCode.RightAlt,\n        })\n    end)\n    if not ok or type(result) ~= "table" then\n        runtimeEnv.NexusStage("UI window failed")\n        runtimeEnv.NexusReport("Nexus UI failed", "CreateWindow: " .. tostring(result))\n        return\n    end\n    Window = result\nend\n\nlocal Fishing = NexusState.Fishing\nlocal MiscFlags = NexusState.MiscFlags\n\n-- ============================================================\n-- ===== SHARED HELPERS (DECLARED UP FRONT) =====\n-- ============================================================\n\nlocal function GetPlayerData()\n    if not Data then return nil end\n    return Data:FindFirstChild(tostring(LocalPlayer.UserId))\nend\n\nlocal function GetModule(folder, name)\n    local m = folder:FindFirstChild(name)\n    if m then\n        local ok, mod = pcall(require, m)\n        if ok and type(mod) == "table" then return mod end\n    end\n    return nil\nend\n\nlocal function GetAvailableBaits()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local baits = {}\n    local baitFolder = p:FindFirstChild("Bait")\n    if not baitFolder then return {} end\n    for _, b in pairs(baitFolder:GetChildren()) do\n        if typeof(b) == "Instance" and typeof(b) == "Instance" and b:IsA("NumberValue") and b.Value > 0 then\n            table.insert(baits, b.Name)\n        end\n    end\n    return baits\nend\n\nlocal function GetBaitStats(baitName)\n    local mod = GetModule(Info.Bait, baitName)\n    if mod then return {Luck = mod.Luck or 0} end\n    return {Luck = 0}\nend\n\nlocal function GetBestBait()\n    local baits = GetAvailableBaits()\n    local best, bestLuck = nil, -1\n    for _, name in ipairs(baits) do\n        local s = GetBaitStats(name)\n        if s.Luck > bestLuck then bestLuck = s.Luck; best = name end\n    end\n    return best\nend\n\nlocal function EquipBait(baitName)\n    if not baitName then return false end\n    return pcall(function() Events.EquipBait:InvokeServer(baitName) end)\nend\n\nlocal function GetOwnedRods()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local rods = {}\n    for _, f in pairs(p.FishingRodInventory:GetChildren()) do\n        if typeof(f) == "Instance" and typeof(f) == "Instance" and f:IsA("Folder") and f.Owned and f.Owned.Value == true then\n            table.insert(rods, f.Name)\n        end\n    end\n    return rods\nend\n\nlocal function GetRodStats(rodName)\n    local mod = GetModule(Info.Inventory, rodName)\n    if mod then return {Power = mod.Power or 0, Luck = mod.Luck or 0} end\n    return {Power = 0, Luck = 0}\nend\n\nlocal function GetB',
