type(serverNonce) == "string" and #serverNonce >= 8 and handoffTier == "PREMIUM" then\n        isValidHandoff = true\n    elseif _rt.NexusPremiumVerified == true and type(_rt.Key) == "string" and #_rt.Key >= 6 and handoffTier == "PREMIUM" then\n        isValidHandoff = true\n    end\n\n    -- X\xC3\xB3a to\xC3\xA0n b\xE1\xBB\x99 c\xE1\xBB\x9D runtime \xC4\x91\xE1\xBB\x83 kh\xC3\xB4ng b\xE1\xBB\x8B t\xC3\xA1i s\xE1\xBB\xAD d\xE1\xBB\xA5ng\n    _rt.NexusPremiumVerified = nil\n    _rt.NexusFreemiumVerified = nil\n    _rt.NexusMainLoaded = nil\n    _rt.NexusVerifiedTier = nil\n\n    if not isValidHandoff then\n        -- Execute source tr\xE1\xBB\xB1c ti\xE1\xBA\xBFp ho\xE1\xBA\xB7c c\xE1\xBB\x91 t\xC3\xACnh set c\xE1\xBB\x9D gi\xE1\xBA\xA3 m\xE1\xBA\xA1o -> KICK ngay\n        local reason = "Bao mat: Khong the thuc thi Nexus Premium truc tiep. Phai qua loader chinh thuc!"\n        notify(reason)\n        pcall(function()\n            if _rt.NexusReport then\n                _rt.NexusReport("Nexus Security", reason)\n            end\n        end)\n        LP:Kick("Nexus: " .. reason)\n        while true do task.wait(9999) end\n        return\n    end\n\n    _rt.NexusPremiumVerified = true\nend\n-- ===== END ANTI-BYPASS GUARD =====\n\nlocal runtimeEnv = (getgenv and getgenv()) or _G\n\n-- ===== NEXUSLIB LOADER =====\npcall(function() runtimeEnv.NexusStage("tai NexusLib") end)\nlocal NexusLib = runtimeEnv.NexusLib\nif not NexusLib then\n    local LIB_URL = "https://raw.githubusercontent.com/Ngmankhoi/my-hub/main/NexusLib.lua?v=20261011"\n    local source = nil\n    pcall(function()\n        if isfile and readfile and isfile("NexusLib.lua") then\n            local s = readfile("NexusLib.lua")\n            if type(s) == "string" and #s > 5000 and s:find("CreateWindow", 1, true) then source = s end\n        end\n    end)\n    if not source then\n        local reqFn = (syn and syn.request) or http_request or request or (http and http.request) or (fluxus and fluxus.request)\n        if type(reqFn) == "function" then\n            pcall(function()\n                local r = reqFn({ Url = LIB_URL, Method = "GET" })\n                local body = r and (r.Body or r.body)\n                if type(body) == "string" and #body > 5000 then source = body end\n            end)\n        end\n    end\n    if not source then\n        pcall(function() local s = game:HttpGet(LIB_URL); if type(s) == "string" and #s > 5000 then source = s end end)\n    end\n    if not source then\n        pcall(function() local s = game:GetService("HttpService"):GetAsync(LIB_URL); if type(s) == "string" and #s > 5000 then source = s end end)\n    end\n    if not source then\n        local msg = "[Nexus] Could not download NexusLib. This executor lacks HTTP support."\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    if type(loadstring) ~= "function" then\n        pcall(function() runtimeEnv.NexusReport("Nexus: executor not supported", "This executor has no loadstring -> the hub cannot run.\\nUse a different executor.") end)\n        return\n    end\n    local chunk, compileErr = loadstring(source, "@NexusLib.lua")\n    if not chunk then\n        local msg = "[Nexus] NexusLib compile error: " .. tostring(compileErr)\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    local ok, lib = pcall(chunk)\n    if not ok or type(lib) ~= "table" then\n        local msg = "[Nexus] NexusLib runtime error: " .. tostring(lib)\n        pcall(function() print(msg) end)\n        pcall(function() runtimeEnv.NexusReport("Nexus Hub", msg) end)\n        return\n    end\n    NexusLib = lib\n    runtimeEnv.NexusLib = lib\nend\n\nif runtimeEnv.MinigameAnchorLock then pcall(function() runtimeEnv.MinigameAnchorLock:Disconnect() end) end\nif runtimeEnv.NexusFrameConnection then runtimeEnv.NexusFrameConnection:Disconnect() runtimeEnv.NexusFrameConnection = nil end\nif runtimeEnv.NexusBossFightThread then task.cancel(runtimeEnv.NexusBossFightThread) runtimeEnv.NexusBossFightThread = nil end\nif runtimeEnv.NexusFightEnzoThread then task.cancel(runtimeEnv.NexusFightEnzoThread) runtimeEnv.NexusFightEnzoThread = nil end\nif runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) runtimeEnv.NexusRhyLoop = nil end\nif runtimeEnv.AntiAFKConnection then pcall(function() runtimeEnv.AntiAFKConnection:Disconnect() end) runtimeEnv.AntiAFKConnection = nil end\nif runtimeEnv.NexusSpaceGuardConnection then pcall(function() runtimeEnv.NexusSpaceGuardConnection:Disconnect() end) runtimeEnv.NexusSpaceGuardConnection = nil end\nif runtimeEnv.NexusSelectableGuardConnection then pcall(function() runtimeEnv.NexusSelectableGuardConnection:Disconnect() end) runtimeEnv.NexusSelectableGuardConnection = nil end\nif runtimeEnv.NexusNoclipConn then pcall(function() runtimeEnv.NexusNoclipConn:Disconnect() end) runtimeEnv.NexusNoclipConn = nil end\nif runtimeEnv.NexusMinigameConn then pcall(function() runtimeEnv.NexusMinigameConn:Disconnect() end) runtimeEnv.NexusMinigameConn = nil end\nif runtimeEnv.NexusSlamConn then pcall(function() runtimeEnv.NexusSlamConn:Disconnect() end) runtimeEnv.NexusSlamConn = nil end\n\n-- ===== SESSION EPOCH =====\nruntimeEnv.NexusEpoch = (runtimeEnv.NexusEpoch or 0) + 1\nlocal MY_EPOCH = runtimeEnv.NexusEpoch\nlocal function alive() return runtimeEnv.NexusEpoch == MY_EPOCH end\n\n-- ===== SERVICES =====\nlocal Services = {\n    Players = game:GetService("Players"),\n    ReplicatedStorage = game:GetService("ReplicatedStorage"),\n    RunService = game:GetService("RunService"),\n    VirtualUser = game:GetService("VirtualUser"),\n    UserInputService = game:GetService("UserInputService"),\n    Lighting = game:GetService("Lighting"),\n    TweenService = game:GetService("TweenService"),\n    Workspace = game:GetService("Workspace"),\n    Camera = game:GetService("Workspace").CurrentCamera,\n    HttpService = game:GetService("HttpService"),\n    GuiService = game:GetService("GuiService"),\n    TeleportService = game:GetService("TeleportService"),\n    RbxAnalyticsService = game:GetService("RbxAnalyticsService"),\n}\nlocal Players = Services.Players\nlocal ReplicatedStorage = Services.ReplicatedStorage\nlocal RunService = Services.RunService\nlocal VirtualUser = Services.VirtualUser\nlocal UserInputService = Services.UserInputService\nlocal Lighting = Services.Lighting\nlocal TweenService = Services.TweenService\nlocal Workspace = Services.Workspace\nlocal Camera = Services.Camera\n\nlocal LocalPlayer = Players.LocalPlayer\n\n-- ===== GAME DATA =====\nruntimeEnv.NexusStage("waiting for game data (Events/MainGui/Info/Data)")\nlocal Events = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Events", 30)\nif not Events then return end\nlocal StartBossFight = Events:FindFirstChild("StartBossFight")\nlocal BossPhase2Action = Events:FindFirstChild("BossPhase2Action")\nlocal MainGui = runtimeEnv.NexusNeedChild(LocalPlayer:WaitForChild("PlayerGui", 30), "MainGui", 30)\nif not MainGui then return end\nlocal Info = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Info", 30)\nif not Info then return end\nlocal Data = runtimeEnv.NexusNeedChild(ReplicatedStorage, "Data", 30)\nif not Data then return end\n\nfor _, v in pairs(LocalPlayer:WaitForChild("PlayerGui"):GetChildren()) do\n    if v.Name:find("MobileToggle") then v:Destroy() end\nend\npcall(function()\n    for _, v in pairs(game:GetService("CoreGui"):GetChildren()) do\n        if v.Name:find("MobileToggle") then v:Destroy() end\n    end\nend)\n\nlocal CODES = {\n    "BigUPD", "23MVisits", "24MVisits", "25MVisits", "26MVisits",\n    "42KLikes", "43KLikes", "44KLikes", "45KLikes", "UIBUG",\n    "33MVisits", "31MVisits", "32MVisits"\n}\n\n-- ============================================================\n-- ===== STATE TABLE =====\n-- ============================================================\nlocal NexusState = {\n    Fishing = {\n        Flags = {\n            MainFarm = true,\n            AutoCast = false,\n            AutoSkill = false,\n            SelectedSkills = { "Z", "X", "C", "V" },\n            SkillMode = "Spam",\n            SkillSequence = "Z,X,C,V",\n            SkillDelay = 0.3,\n            AutoFarmBoss = false,\n            AutoFarmSecretBoss = false,\n            AnchorLock = false,\n            AntiAFK = false,\n            AutoSkillCheck = false,\n            BossFightMode = "Normal",\n            BossFightThread = nil,\n            AutoFightEnzo = false,\n            AutoFightLongDiaohai = false,\n            AutoLongDiaohai = false,\n            LongDiaohaiFightMode = "Normal",\n            LastCancel = 0,\n            LastFastCancel = 0,\n            LastProgress = 0,\n            LastNotify = ""\n        },\n        BossFarm = {\n            CurrentTarget = nil,\n            CurrentType = nil,\n            CurrentToken = nil,\n            CurrentRunId = 0,\n            HasHooked = false,\n            PendingCancel = false,\n            LastCast = 0,\n            LastCancel = 0,\n            LastFastCancel = 0,\n            LastProgress = 0,\n            LastNotify = ""\n        }\n    },\n    MiscFlags = {\n        FlyMode = false,\n        Noclip = false,\n        InfiniteJump = false,\n        WalkOnWater = false,\n        FullBright = false,\n        AutoSell = false,\n        AutoBuy = false,\n        AutoEquipBait = false,\n        AutoEquipRod = false,\n    },\n    islands = {\n        {name = "Island 1", cframe = CFrame.new(-297, 9, 12), power = 0},\n        {name = "Island 2", cframe = CFrame.new(-1274, 21, -270), power = 17},\n        {name = "Island 3", cframe = CFrame.new(57, 9, 1115), power = 28},\n        {name = "Island 4", cframe = CFrame.new(-1343, 9, 1083), power = 35},\n        {name = "Island 5", cframe = CFrame.new(-12, 9, -1696), power = 45},\n        {name = "Island 6", cframe = CFrame.new(-1184, 20, -1652), power = 55},\n        {name = "Island 7", cframe = CFrame.new(1470, 9, -1685), power = 62},\n        {name = "Island 8", cframe = CFrame.new(1130, 9, 1364), power = 72},\n        {name = "Island 9", cframe = CFrame.new(1459, 8, -248), power = 90},\n        {name = "Island 10", cframe = CFrame.new(3028, 16, -124), power = 100},\n        -- Island 11 (if u have ego and tiger): chi duoc recommend khi co ca rod Ego va Tiger\n        {name = "Island 11", cbel") and val.Text or val.Value))\n                        return text:gsub("Weather:%s*", ""):lower():gsub("^%s+", ""):gsub("%s+$", "")\n                    end\n                end\n            end\n        end\n        return "clear"\n    end\n\n    while true do\n        task.wait(1.5)\n        if not alive() then break end\n        if NexusState.SmartWeather and NexusState.SmartWeather.enabled then\n            pcall(function()\n                local currentWeather = getActiveWeather()\n                local matchedIsland = weatherIslandsMap[currentWeather]\n\n                if matchedIsland and (currentWeather ~= "clear" and currentWeather ~= "") and NexusState.SmartWeather.selectedIslands[matchedIsland] then\n                    if not NexusState.SmartWeather.activeOverride then\n                        local char = LocalPlayer.Character\n                        local hrp = char and char:FindFirstChild("HumanoidRootPart")\n                        if hrp then\n                            NexusState.SmartWeather.savedCFrame = hrp.CFrame\n                            NexusState.SmartWeather.savedFlags = {\n                                AutoCast = Fishing.Flags.AutoCast,\n                                AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n                                AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n                                AnchorLock = Fishing.Flags.AnchorLock,\n                                AutoSkill = Fishing.Flags.AutoSkill,\n                                AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n                                AntiAFK = Fishing.Flags.AntiAFK,\n                            }\n                            NexusState.SmartWeather.activeOverride = true\n                            NexusState.SmartWeather.targetIsland = matchedIsland\n\n                            for _, v in ipairs(NexusState.islands) do\n                                if v.name:lower() == matchedIsland:lower() then\n                                    hrp.AssemblyLinearVelocity = Vector3.zero\n                                    hrp.AssemblyAngularVelocity = Vector3.zero\n                                    hrp.CFrame = CFrame.new(v.cframe.Position + Vector3.new(0, 5, 0))\n                                    break\n                                end\n                            end\n\n                            Fishing.Flags.AutoCast = false\n                            Fishing.Flags.AutoFarmBoss = false\n                            Fishing.Flags.AutoFarmSecretBoss = true\n                            Fishing.Flags.AnchorLock = true\n                            Fishing.Flags.AutoSkill = true\n                            Fishing.Flags.AutoSkillCheck = true\n                            Fishing.Flags.AntiAFK = true\n\n                            NexusLib:Notify({\n                                Title = "Farm On Weather",\n                                Message = "Weather detected: " .. currentWeather:upper() .. "! Auto-hopping to " .. matchedIsland .. " cau Secret.",\n                                Duration = 4\n                            })\n                        end\n                    end\n                else\n                    if NexusState.SmartWeather.activeOverride then\n                        NexusLib:Notify({\n                            Title = "Farm On Weather",\n                            Message = "Weather ended! Returning to the original farm...",\n                            Duration = 3\n                        })\n                        local char = LocalPlayer.Character\n                        local hrp = char and char:FindFirstChild("HumanoidRootPart")\n                        if NexusState.SmartWeather.savedCFrame and hrp then\n                            safeTeleport(hrp, NexusState.SmartWeather.savedCFrame)\n                        end\n                        if NexusState.SmartWeather.savedFlags then\n                            local s = NexusState.SmartWeather.savedFlags\n                            Fishing.Flags.AutoCast = s.AutoCast\n                            Fishing.Flags.AutoFarmBoss = s.AutoFarmBoss\n                            Fishing.Flags.AutoFarmSecretBoss = s.AutoFarmSecretBoss\n                            Fishing.Flags.AnchorLock = s.AnchorLock\n                            Fishing.Flags.AutoSkill = s.AutoSkill\n                            Fishing.Flags.AutoSkillCheck = s.AutoSkillCheck\n                            Fishing.Flags.AntiAFK = s.AntiAFK\n                        end\n                        NexusState.SmartWeather.activeOverride = false\n                        NexusState.SmartWeather.savedCFrame = nil\n                        NexusState.SmartWeather.savedFlags = nil\n                        NexusState.SmartWeather.targetIsland = nil\n                    end\n                end\n            end)\n        end\n    end\nend)\n\ntask.spawn(function()\n    while task.wait(1) do\n        if not alive() then break end\n        if bossFarmEnabled() then\n            local character = LocalPlayer.Character\n            local fishingGui = MainGui:FindFirstChild("Fishing")\n            if character and character:GetAttribute("Fishing") then\n                if Fishing.BossFarm.PendingCancel then\n                    cancelOrReleaseNormalFish()\n                elseif Fishing.BossFarm.HasHooked and fishingGui and fishingGui.Visible then\n                    local target = getCurrentHookTarget()\n                    local shouldFarm = shouldFarmBossTarget(target)\n                    if shouldFarm then\n                        Fishing.BossFarm.PendingCancel = false\n                        farmHookedBoss(target)\n                    elseif target.Name and target.Name ~= "???" then\n                        Fishing.BossFarm.PendingCancel = true\n                        cancelOrReleaseNormalFish()\n                    end\n                end\n            else\n                resetBossFarmTarget()\n                castRod()\n            end\n        end\n    end\nend)\n\n-- AUTO SELL\ndo\n    local function getInventoryCount()\n        local _icNow = tick()\n        if NexusState.cachedInvCount and NexusState.cachedInvCountAt and (_icNow - NexusState.cachedInvCountAt < 5) then\n            return NexusState.cachedInvCount\n        end\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return 0 end\n        local inv = userData:FindFirstChild("Inventory")\n        if not inv then return 0 end\n        local count = 0\n        for _ in pairs(inv:GetChildren()) do count = count + 1 end\n        NexusState.cachedInvCount = count\n        NexusState.cachedInvCountAt = _icNow\n        return count\n    end\n\n    local function getInventoryLimit()\n        local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n        if not userData then return 0 end\n        local limit = userData:FindFirstChild("InventoryLimit")\n        if limit and typeof(limit) == "Instance" and limit:IsA("NumberValue") then return limit.Value end\n        return 0\n    end\n\n    local function getSellSofa()\n        local map = Workspace:FindFirstChild("Map")\n        if map then\n            local map1 = map:FindFirstChild("Map 1")\n            if map1 then\n                local build = map1:FindFirstChild("Build")\n                if build then\n                    local sellFish = build:FindFirstChild("SellFish")\n                    if sellFish then\n                        return sellFish:FindFirstChild("Sofa")\n                    end\n                end\n            end\n        end\n        return nil\n    end\n\n    local function getSofaPosition()\n        local sofa = getSellSofa()\n        if sofa then\n            local hrp = sofa:FindFirstChild("HumanoidRootPart")\n            if hrp then return hrp.Position end\n            local primary = sofa.PrimaryPart\n            if primary then return primary.Position end\n            for _, part in ipairs(sofa:GetDescendants()) do\n                if typeof(part) == "Instance" and part:IsA("BasePart") then\n                    return part.Position\n                end\n            end\n        end\n        return nil\n    end\n\n    local function teleportToSofa()\n        local pos = getSofaPosition()\n        if not pos then return false end\n        local char = LocalPlayer.Character\n        if not char then return false end\n        local hrp = char:FindFirstChild("HumanoidRootPart")\n        if not hrp then return false end\n        NexusState.lastPosition = hrp.Position\n        hrp.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0))\n        return true\n    end\n\n    local function teleportBack()\n        if not NexusState.lastPosition then return end\n        local char = LocalPlayer.Character\n        if not char then return end\n        local hrp = char:FindFirstChild("HumanoidRootPart")\n        if not hrp then return end\n        safeTeleport(hrp, CFrame.new(NexusState.lastPosition))\n        NexusState.lastPosition = nil\n    end\n\n    local function doSell()\n        if not MiscFlags.AutoSell then return end\n        if tick() - (NexusState.sellCooldown or 0) < 0.5 then return end\n        NexusState.sellCooldown = tick()\n        local method1 = NexusState.sellMethod1 or "Spam"\n        local method2 = NexusState.sellMethod2 or "Instant"\n        if method1 == "When full" then\n            local count = getInventoryCount()\n            local limit = getInventoryLimit()\n            if limit == 0 then return end\n            if count < limit - 3 then return end\n        end\n        local teleported = false\n        if method2 == "Teleport" then\n            teleported = teleportToSofa()\n            if teleported then task.wait(0.3) end\n        end\n        pcall(function() Events.SellFish:FireServer("All") end)\n        if teleported then\n            task.wait(0.2)\n            teleportBack()\n        end\n    end\n\n    task.spawn(function()\n        while task.wait(2) do\n            if not alive() then break end\n            pcall(doSell)\n        end\n    end)\nend\n\nif runtimeEnv.NexusMinigameConn then pcall(function() runtimeEnv.NexusMinigameConn:Disconnect() end) end\nruntimeEnv.NexusMinigameConn = Events.FishingMinigame.OnClientEvent:Connect(function(p1, p2, p3)\n    if not p1 or not p2 then return end\n    Fishing.BossFarm.CurrentTarget = p1\n    Fishing.BossFarm.CurrentToken = p3\n    Fishing.BossFarm.HasHooked = true\n    Fishing.BossFarm.PendingCancel = false\n    Fishing.BossFarm.CurrentRunId = Fishing.BossFarm.CurrentRunId + 1\n    local runId = Fishing.BossFarm.CurrentRunId\n    local target = getCurrentHookTarget()\n    local shouldFarm = shouldFarmBossTarget(target)\n    if bossFarmEnabled() and not shouldFarm then\n        Fishing.BossFarm.PendingCancel = true\n        task.delay(0.15, cancelOrReleaseNormalFish)\n        return\n    end\n    if Fishing.Flags.AutoCast or (bossFarmEnabled() and shouldFarm) then\n        task.spawn(function()\n            local minigameActive = true\n            local connection\n            local fishingGui = MainGui:FindFirstChild("Fishing")\n            if fishingGui then\n                connection = fishingGui:GetPropertyChangedSignal("Visible"):Connect(function()\n                    if not fishingGui.Visible then\n                        minigameActive = false\n                        if connection then connection:Disconnect() connection = nil end\n                    end\n                end)\n            end\n            while minigameActive do\n                if not alive() then break end\n                if not MainGui:FindFirstChild("Fishing") or not MainGui.Fishing.Visible then break end\n                if bossFarmEnabled() then\n                    if runId ~= Fishing.BossFarm.CurrentRunId then break end\n                    target = getCurrentHookTarget()\n                    shouldFarm = shouldFarmBossTargestRod()\n    local rods = GetOwnedRods()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(rods) do\n        local s = GetRodStats(name)\n        local score = s.Power + s.Luck\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipRod(rodName)\n    if not rodName then return false end\n    return pcall(function() Events.EquipFishingRod:InvokeServer(rodName) end)\nend\n\nlocal function GetAvailableOrbs()\n    local p = GetPlayerData()\n    if not p then return {} end\n    local orbs = {}\n    local orbFolder = p:FindFirstChild("Orb")\n    if not orbFolder then return {} end\n    for _, f in pairs(orbFolder:GetChildren()) do\n        if typeof(f) == "Instance" and typeof(f) == "Instance" and f:IsA("Folder") then\n            local eq = f:FindFirstChild("Equipping")\n            if eq and eq.Value == false then\n                table.insert(orbs, f.Name)\n            end\n        end\n    end\n    return orbs\nend\n\nlocal function GetOrbStats(orbName)\n    local p = GetPlayerData()\n    if not p then return {} end\n    local f = p.Orb:FindFirstChild(orbName)\n    if not f then return {} end\n    local stats = {}\n    for _, child in pairs(f:GetChildren()) do\n        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("NumberValue") and child.Name ~= "Equipping" and child.Name ~= "Favorite" then\n            stats[child.Name] = child.Value\n        end\n    end\n    return stats\nend\n\nlocal function GetBestOrb()\n    local orbs = GetAvailableOrbs()\n    local best, bestScore = nil, -1\n    for _, name in ipairs(orbs) do\n        local s = GetOrbStats(name)\n        local score = (s.Damage or 0) * 2 + (s.Luck or 0) * 1.5 + (s.Cash or 0) * 0.5\n        if score > bestScore then bestScore = score; best = name end\n    end\n    return best\nend\n\nlocal function EquipOrb(orbName)\n    if not orbName then return false end\n    return pcall(function() Events.EquipOrb:InvokeServer(orbName) end)\nend\n\n-- Parse one Data inventory child into (fishName, weightKg, count).\n-- Real server format: Name = "FishName | 3500000 KG" (may add " | Favorite"),\n-- Value = stack count (IntValue). Older format kept as fallback.\nlocal function parseCraftWeight(str)\n    if not str or str == "" then return nil end\n    local s = tostring(str):gsub("^%s+", ""):gsub("%s+$", "")\n    s = s:gsub("%s*[Kk][Gg]%s*$", "")\n    s = s:gsub("^%s+", ""):gsub("%s+$", "")\n    local direct = tonumber(s)\n    if direct then return direct end\n    local num, suffix = s:match("^([%d%.]+)%s*([KkMmBbTt])%+?$")\n    num = tonumber(num)\n    if not num then return nil end\n    local mult = { K = 1000, M = 1000000, B = 1000000000, T = 1000000000000 }\n    local m = mult[string.upper(suffix or "")]\n    if not m then return nil end\n    return num * m\nend\n\nlocal function parseCraftFishEntry(item)\n    if not item then return nil, nil, 0 end\n    local rawName = tostring(item.Name or "")\n    rawName = string.split(rawName, "| Favorite")[1]\n    local count = 1\n    pcall(function()\n        if type(item.Value) == "number" then count = item.Value end\n    end)\n    local parts = {}\n    for part in string.gmatch(rawName, "[^|]+") do table.insert(parts, part) end\n    local function trim(s) return tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "") end\n    local fishName = trim(parts[1])\n    local weight = nil\n    if #parts >= 2 then\n        weight = parseCraftWeight(string.split(trim(parts[2]), " ")[1])\n    end\n    if not weight then\n        pcall(function()\n            local w = item:GetAttribute("Weight")\n            if type(w) == "number" and w > 0 then weight = w end\n        end)\n    end\n    if (not weight) and type(item.Value) == "string" and string.find(item.Value, "|", 1, true) then\n        local vparts = {}\n        for part in string.gmatch(item.Value, "[^|]+") do table.insert(vparts, part) end\n        if #vparts >= 2 then\n            weight = parseCraftWeight(string.split(trim(vparts[2]), " ")[1])\n        end\n        if fishName == "" and #vparts >= 1 then fishName = trim(vparts[1]) end\n    end\n    if fishName == "" then return nil, nil, 0 end\n    if type(count) ~= "number" or count < 1 then count = 1 end\n    return fishName, weight, math.floor(count)\nend\n\nlocal function GetBuyableBaits()\n    local _bbNow = tick()\n    if NexusState.cachedBuyableBaits and NexusState.cachedBuyableBaitsAt and (_bbNow - NexusState.cachedBuyableBaitsAt < 30) then\n        return NexusState.cachedBuyableBaits\n    end\n    local baits = {}\n    if not Info or not Info:FindFirstChild("Bait") then return {"No bait available"} end\n    for _, child in pairs(Info.Bait:GetChildren()) do\n        if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("ModuleScript") then\n            local success, mod = pcall(require, child)\n            if success and type(mod) == "table" and mod.Price and mod.Price > 0 then\n                table.insert(baits, child.Name)\n            end\n        end\n    end\n    if #baits == 0 then return {"No bait available"} end\n    NexusState.cachedBuyableBaits = baits\n    NexusState.cachedBuyableBaitsAt = _bbNow\n    return baits\nend\n\nlocal function saveRoutineFlags()\n    NexusState.savedRoutineFlags = {\n        AutoCast = Fishing.Flags.AutoCast,\n        AnchorLock = Fishing.Flags.AnchorLock,\n        AutoSkill = Fishing.Flags.AutoSkill,\n        AutoSell = MiscFlags.AutoSell,\n        AutoSkillCheck = Fishing.Flags.AutoSkillCheck,\n        AntiAFK = Fishing.Flags.AntiAFK,\n        AutoFarmBoss = Fishing.Flags.AutoFarmBoss,\n        AutoFarmSecretBoss = Fishing.Flags.AutoFarmSecretBoss,\n        AutoBuy = MiscFlags.AutoBuy,\n        AutoEquipBait = MiscFlags.AutoEquipBait,\n        AutoEquipRod = MiscFlags.AutoEquipRod,\n    }\nend\n\nlocal function restoreRoutineFlags()\n    if NexusState.savedRoutineFlags then\n        Fishing.Flags.AutoCast = NexusState.savedRoutineFlags.AutoCast\n        Fishing.Flags.AnchorLock = NexusState.savedRoutineFlags.AnchorLock\n        Fishing.Flags.AutoSkill = NexusState.savedRoutineFlags.AutoSkill\n        MiscFlags.AutoSell = NexusState.savedRoutineFlags.AutoSell\n        Fishing.Flags.AutoSkillCheck = NexusState.savedRoutineFlags.AutoSkillCheck\n        Fishing.Flags.AntiAFK = NexusState.savedRoutineFlags.AntiAFK\n        Fishing.Flags.AutoFarmBoss = NexusState.savedRoutineFlags.AutoFarmBoss\n        Fishing.Flags.AutoFarmSecretBoss = NexusState.savedRoutineFlags.AutoFarmSecretBoss\n        MiscFlags.AutoBuy = NexusState.savedRoutineFlags.AutoBuy\n        MiscFlags.AutoEquipBait = NexusState.savedRoutineFlags.AutoEquipBait\n        MiscFlags.AutoEquipRod = NexusState.savedRoutineFlags.AutoEquipRod\n        NexusState.savedRoutineFlags = nil\n    else\n        Fishing.Flags.AutoFarmBoss = false\n        Fishing.Flags.AutoFarmSecretBoss = false\n    end\nend\n\n-- Ticket fishing mode: auto cast + anchor lock + auto skill + rod equip,\n-- so turning on Auto Do Ticket is enough to work all 8 ticket quests.\nlocal function enableBasicFishing()\n    if not NexusState.savedRoutineFlags then saveRoutineFlags() end\n    Fishing.Flags.AutoCast = true\n    Fishing.Flags.AnchorLock = true\n    Fishing.Flags.AutoSkill = true\n    Fishing.Flags.AutoSkillCheck = true\n    MiscFlags.AutoEquipRod = true\nend\n\nlocal function disableAllFishing()\n    restoreRoutineFlags()\nend\n\n-- Teleport without the sky-drop freeze: a character held at +1000 sky sits in\n-- freefall, so AssemblyLinearVelocity grows huge. Carrying that velocity into a\n-- ground teleport slams the Humanoid into the floor and sticks it (frozen).\n-- Zero it on both ends and wake the Humanoid so movement resumes instantly.\nlocal function safeTeleport(hrp, cf)\n    if not hrp or not cf then return end\n    local model = hrp.Parent\n    local humanoid = model and model:FindFirstChildOfClass("Humanoid")\n    -- Never freeze the live character: Anchored + task.wait() inside a\n    -- RenderStepped/Heartbeat-adjacent call stalls physics for a frame and\n    -- leaves the Humanoid seated/stuck, so walking looks frozen afterwards.\n    -- PivotTo moves the whole model atomically with no Anchored pin.\n    local ok = false\n    if model then\n        pcall(function()\n            model:PivotTo(cf)\n            ok = true\n        end)\n    end\n    if not ok then\n        pcall(function()\n            hrp.AssemblyLinearVelocity = Vector3.zero\n            hrp.AssemblyAngularVelocity = Vector3.zero\n            hrp.CFrame = cf\n        end)\n    end\n    pcall(function()\n        hrp.Anchored = false\n        hrp.AssemblyLinearVelocity = Vector3.zero\n        hrp.AssemblyAngularVelocity = Vector3.zero\n    end)\n    if humanoid then\n        pcall(function()\n            if humanoid.Seated then humanoid.Seated = false end\n            humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)\n        end)\n    end\nend\n\n-- ===== EGO + TIGER CHECK (dieu kien cho Island 11) =====\n-- Island 11 chi duoc recommend khi user co ca rod Ego va Tiger trong kho.\nlocal function hasEgoAndTiger()\n    local p = GetPlayerData()\n    if not p then return false end\n    local rodFolder = p:FindFirstChild("FishingRodInventory") or p:FindFirstChild("Rod")\n    if not rodFolder then return false end\n    local hasEgo, hasTiger = false, false\n    for _, f in pairs(rodFolder:GetChildren()) do\n        local n = string.lower(tostring(f.Name))\n        if string.find(n, "ego") then hasEgo = true end\n        if string.find(n, "tiger") then hasTiger = true end\n    end\n    return hasEgo and hasTiger\nend\n\nlocal function getTotalPower()\n    local _pwNow = tick()\n    if NexusState.cachedPower and NexusState.cachedPowerAt and (_pwNow - NexusState.cachedPowerAt < 5) then\n        return NexusState.cachedPower\n    end\n    local total = 0\n    local char = LocalPlayer.Character\n    if char then\n        local stats = char:FindFirstChild("Stats")\n        if stats then\n            local rp = stats:FindFirstChild("RodPower")\n            if typeof(rp) == "Instance" and rp:IsA("NumberValue") then total = total + rp.Value end\n            local fp = stats:FindFirstChild("FishPower")\n            if typeof(fp) == "Instance" and fp:IsA("NumberValue") then total = total + fp.Value end\n        end\n        local attr = char:GetAttribute("RodPower")\n        if attr and type(attr) == "number" and attr > 0 and total == 0 then total = attr end\n    end\n    if total == 0 then\n        local userId = LocalPlayer.UserId\n        local userData = Data:FindFirstChild(tostring(userId))\n        if userData then\n            local rodNameValue = userData:FindFirstChild("FishingRod")\n            if rodNameValue then\n                local rodName = rodNameValue.Value\n                if rodName and rodName ~= "" then\n                    local rodModule = Info:FindFirstChild("Inventory") and Info.Inventory:FindFirstChild(rodName)\n                    if rodModule then\n                        local success, rodData = pcall(require, rodModule)\n                        if success and type(rodData) == "table" then\n                            total = rodData.Power or 0\n                        end\n                    end\n                end\n            end\n        end\n    end\n    NexusState.cachedPower = total\n    NexusState.cachedPowerAt = _pwNow\n    return total\nend\n\nlocal function getRecommendedIsland()\n    local _rcNow = tick()\n    if NexusState.cachedRecommended and NexusState.cachedRecommendedAt and (_rcNow - NexusState.cachedRecommendedAt < 5) then\n        return NexusState.cachedRecommended\n    end\n    local currentPower = getTotalPower()\n    local eligible = {}\n    for _, island in ipairs(NexusState.islands) do\n        -- Island 11: only picked with Ego + Tiger rods\n        local islandOk = true\n        if island.name == "Island 11" then\n            if not hasEgoAndTiger() aP\xAA\x04Text\xAB\xF3\xCF\x00\xC1\xCCL\x06#\nA\x03',
