task.cancel(          if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = "NPC Teleport", Message = "Teleported to " .. selectedNpc, Duration = 2 })\n            end\n        })\n        -- ===== LEARN SKILL NPC =====\n        local selectedLearnNpc = "Sage Yijiu"\n        \n        -- Dropdown with a single option\n        local learnDropdown = Cfg.register(NpcSection:CreateDropdown(Cfg.wrap("Dropdown", "Learn Skill NPC", {\n            Name = "Learn Skill NPC",\n            Options = {"Sage Yijiu"},\n            Default = "Sage Yijiu",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })), "Dropdown", "Learn Skill NPC", {\n            Name = "Learn Skill NPC",\n            Options = {"Sage Yijiu"},\n            Default = "Sage Yijiu",\n            Callback = function(value)\n                selectedLearnNpc = value\n            end\n        })\n        \n        -- Teleport to selected NPC button\n        NpcSection:CreateButton({\n            Name = "Teleport to selected NPC",\n            Callback = function()\n                local targetModel = workspace:FindFirstChild("NPC") \n                    and workspace.NPC:FindFirstChild("LearnSkill") \n                    and workspace.NPC.LearnSkill:FindFirstChild("Sage Yijiu")\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = "Learn Skill", Message = "Sage Yijiu not found!", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild("HumanoidRootPart") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA("BasePart")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = "Learn Skill", Message = "Cannot find part to teleport to!", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild("HumanoidRootPart")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = "Learn Skill", Message = "Teleported to Sage Yijiu", Duration = 2 })\n            end\n        })\n        -- ===== SECRET RODS SECTION =====\n        -- Secret Rod list (models parented to a Folder under workspace.SecretRod)\n        local function getSecretRodList()\n            local rods = {}\n            local secretRodFolder = workspace:FindFirstChild("SecretRod")\n            if not secretRodFolder then return rods end\n            \n            for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                if typeof(child) == "Instance" and child:IsA("Model") and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                    table.insert(rods, child.Name)\n                end\n            end\n            return rods\n        end\n        \n        local rodList = getSecretRodList()\n        if #rodList == 0 then\n            table.insert(rodList, "No Secret Rods found")\n        end\n        \n        local selectedRod = rodList[1]\n        \n        -- Dropdown\n        local rodDropdown = NpcSection:CreateDropdown({\n            Name = "Secret Rods",\n            Options = rodList,\n            Default = selectedRod,\n            Callback = function(value)\n                selectedRod = value\n            end\n        })\n        \n        -- Teleport button\n        NpcSection:CreateButton({\n            Name = "Teleport to selected Secret Rod",\n            Callback = function()\n                if not selectedRod or selectedRod == "No Secret Rods found" then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "No Secret Rod selected!", Duration = 2 })\n                    return\n                end\n                \n                local secretRodFolder = workspace:FindFirstChild("SecretRod")\n                if not secretRodFolder then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "SecretRod folder not found!", Duration = 2 })\n                    return\n                end\n                \n                local targetModel = nil\n                for _, child in ipairs(secretRodFolder:GetDescendants()) do\n                    if typeof(child) == "Instance" and child:IsA("Model") and child.Name == selectedRod and child.Parent and typeof(child.Parent) == "Instance" and child.Parent:IsA("Folder") then\n                        targetModel = child\n                        break\n                    end\n                end\n                \n                if not targetModel then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "Secret Rod not found!", Duration = 2 })\n                    return\n                end\n                \n                local hrp = targetModel:FindFirstChild("HumanoidRootPart") or targetModel.PrimaryPart\n                if not hrp then\n                    hrp = targetModel:FindFirstChildWhichIsA("BasePart")\n                end\n                if not hrp then\n                    NexusLib:Notify({ Title = "Secret Rod", Message = "Cannot find part to teleport to!", Duration = 2 })\n                    return\n                end\n                \n                local myChar = LocalPlayer.Character\n                if not myChar then return end\n                local myHrp = myChar:FindFirstChild("HumanoidRootPart")\n                if not myHrp then return end\n                \n                myHrp.CFrame = hrp.CFrame + Vector3.new(0, 3, 0)\n                \n                NexusLib:Notify({ Title = "Secret Rod", Message = "Teleported to " .. selectedRod, Duration = 2 })\n            end\n        })\n    end\nend\n\n-- ============================================================\n-- ===== SETTINGS TAB =====\n-- ============================================================\ndo\n    local SettingsTab = Window:CreateTab("Settings")\n\n    -- ===== CONFIG SECTION (save / load / auto-load / import-export) =====\n    do\n        local CfgUI = SettingsTab:CreateSection("Config")\n        local Cfg = runtimeEnv.NexusConfig\n\n        CfgUI:CreateButton({\n            Name = "Save Config",\n            Callback = function() Cfg.save() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = "Load Config",\n            Callback = function() Cfg.load() end,\n        })\n\n        CfgUI:CreateToggle({\n            Name = "Auto Load Config",\n            Default = false,\n            Callback = function(value)\n                if not (writefile and isfile) then\n                    NexusLib:Notify({ Title = "Config", Message = "This executor cannot save files.", Duration = 3 })\n                    return\n                end\n                if value then\n                    Cfg.save(Cfg.AUTO_FILE)\n                else\n                    pcall(function()\n                        if isfile(Cfg.AUTO_FILE) and delfile then delfile(Cfg.AUTO_FILE) end\n                    end)\n                end\n            end,\n        })\n\n        CfgUI:CreateButton({\n            Name = "Export Config (Copy Code)",\n            Callback = function() Cfg.exportCode() end,\n        })\n\n        local importBox = CfgUI:CreateTextbox({\n            Name = "Import Config Code",\n            Placeholder = "Paste code, then press Import",\n            Default = "",\n            Callback = function() end,\n        })\n\n        CfgUI:CreateButton({\n            Name = "Import Config",\n            Callback = function()\n                local code = ""\n                pcall(function() code = importBox.Get() end)\n                Cfg.importCode(code)\n            end,\n        })\n    end\n    local CharSection = SettingsTab:CreateSection("Character")\n\n    Cfg.register(CharSection:CreateTextbox(Cfg.wrap("Textbox", "Walk Speed", { Name = "Walk Speed", Placeholder = "16", Default = "16", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })), "Textbox", "Walk Speed", { Name = "Walk Speed", Placeholder = "16", Default = "16", Callback = function(V)\n        pcall(function() LocalPlayer.Character.Humanoid.WalkSpeed = tonumber(V) or 16 end)\n    end })\n\n    local function startFly()\n        local c = LocalPlayer.Character\n        if not c or not c:FindFirstChild("HumanoidRootPart") then return end\n        if NexusState.flying then return end\n        if NexusState.bg then NexusState.bg:Destroy() end\n        if NexusState.bv then NexusState.bv:Destroy() end\n        local h = c.HumanoidRootPart\n        NexusState.bg = Instance.new("BodyGyro", h)\n        NexusState.bg.P = 9e4\n        NexusState.bg.maxTorque = Vector3.new(9e9,9e9,9e9)\n        NexusState.bg.cframe = h.CFrame\n        NexusState.bv = Instance.new("BodyVelocity", h)\n        NexusState.bv.velocity = Vector3.new(0,0,0)\n        NexusState.bv.maxForce = Vector3.new(9e9,9e9,9e9)\n        NexusState.flying = true\n        local humanoid = c:FindFirstChildOfClass("Humanoid")\n        if humanoid then humanoid.PlatformStand = true end\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect() end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect() end\n        NexusState.flyInputConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)\n            if gameProcessed then return end\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = true end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = true end\n        end)\n        NexusState.flyInputEndConnection = UserInputService.InputEnded:Connect(function(input)\n            if input.KeyCode == Enum.KeyCode.Space then NexusState.flyKeys.Up = false end\n            if input.KeyCode == Enum.KeyCode.LeftControl then NexusState.flyKeys.Down = false end\n        end)\n    end\n\n    local function stopFly()\n        NexusState.flying = false\n        NexusState.flyKeys.Up, NexusState.flyKeys.Down = false, false\n        if NexusState.flyInputConnection then NexusState.flyInputConnection:Disconnect(); NexusState.flyInputConnection = nil end\n        if NexusState.flyInputEndConnection then NexusState.flyInputEndConnection:Disconnect(); NexusState.flyInputEndConnection = nil end\n        if NexusState.bg then NexusState.bg:Destroy(); NexusState.bg = nil end\n        if NexusState.bv then NexusState.bv:Destroy(); NexusState.bv = nil end\n        local c = LocalPlayer.Character\n        if c then\n            local humanoid = c:FindFirstChildOfClass("Humanoid")\n            if humanoid then humanoid.PlatformStand = false end\n        end\n    end\n\n    Cfg.register(CharSection:CreateToggle(Cfg.wrap("Toggle", "Fly Mode", { Name = "Fly Mode", Default = false, Callback = function(V)\n        MiscFlags.FlyMode = V\n        if V then startFly() else stopFly() end\n    end })), "Toggle", "Fly Mode", { Name = "Fly Mode", Default = false, Callback = function(V)\n        MiscFlags.FlyMode = V\n        if V then startFly() else stopFly() end\n    end })\n    Cfg.register(CharSection:CreateTextbox(Cfg.wrap("Textbox", "Fly Speed", { Name = "Fly Speed", Placeholder = "50", Default = "50", Callback = function(V)\n        NexusState.flySpeed = tonumber(V) or 50\n    end })), "Textbox", "Fly Speed", { Name = "Fly Speed", Placeholder = "50", Default = "50", Callback = function(V)\n        NexusState.flySpeed = tonumber(V) or 50\n    end })\n    Cfg.register(CharSection:C",\n        Callback = function()\n            local taoist = nil\n            for _, v in pairs(Workspace:GetDescendants()) do\n                if typeof(v) == "Instance" and typeof(v) == "Instance" and v:IsA("Model") and string.find(v.Name:lower(), "taoist") and v:FindFirstChild("HumanoidRootPart") then\n                    taoist = v\n                    break\n                end\n            end\n            if taoist and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = taoist.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)\n                NexusLib:Notify({ Title = "Taoist", Message = "Teleported!", Duration = 3 })\n            else\n                NexusLib:Notify({ Title = "Taoist", Message = "Not found!", Duration = 3 })\n            end\n        end\n    })\n\n    TPSection:CreateButton({\n        Name = "TP to Maoshan",\n        Callback = function()\n            local maoshan = nil\n            for _, v in pairs(Workspace:GetDescendants()) do\n                if typeof(v) == "Instance" and typeof(v) == "Instance" and v:IsA("Model") and (string.find(v.Name:lower(), "maoshan") or string.find(v.Name:lower(), "merchant")) and v:FindFirstChild("HumanoidRootPart") then\n                    maoshan = v\n                    break\n                end\n            end\n            if maoshan and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart") then\n                LocalPlayer.Character.HumanoidRootPart.CFrame = maoshan.HumanoidRootPart.CFrame * CFrame.new(0, 0, 4)\n                NexusLib:Notify({ Title = "Maoshan", Message = "Teleported!", Duration = 3 })\n            else\n                NexusLib:Notify({ Title = "Maoshan", Message = "Not found!", Duration = 3 })\n            end\n        end\n    })\n\n    TPSection:CreateButton({\n        Name = "TP to Spirit",\n        Callback = function()\n            local godFolder = Workspace:FindFirstChild("NPC") and Workspace.NPC:FindFirstChild("God")\n            if not godFolder then\n                NexusLib:Notify({ Title = "Spirit", Message = "Folder God not found!", Duration = 3 })\n                return\n            end\n            local target = nil\n            for _, child in pairs(godFolder:GetChildren()) do\n                if typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("Model") then\n                    local hrp = child:FindFirstChild("HumanoidRootPart")\n                    if hrp then\n                        target = hrp\n                        break\n                    end\n                elseif typeof(child) == "Instance" and typeof(child) == "Instance" and child:IsA("BasePart") then\n                    target = child\n                    break\n                end\n            end\n            if not target then\n                NexusLib:Notify({ Title = "Spirit", Message = "No Spirit found!", Duration = 3 })\n                return\n            end\n            local char = LocalPlayer.Character\n            if not char then return end\n            local hrp = char:FindFirstChild("HumanoidRootPart")\n            if hrp then\n                hrp.CFrame = target.CFrame + Vector3.new(0, 3, 0)\n                NexusLib:Notify({ Title = "Spirit", Message = "Teleported to Spirit!", Duration = 3 })\n            end\n        end\n    })\n\n    -- ===== NPC TELEPORT + GIVE FISH (Duan Gan / Dumb guy) =====\n    do\n        local GiveSection = TeleportTab:CreateSection("Quest NPC & Give Fish", "Right")\n\n        local function npcRoot()\n            return Workspace:FindFirstChild("NPC")\n        end\n\n        local function findNpcHrp(npcName)\n            local hrp = nil\n            pcall(function()\n                local npcFolder = npcRoot()\n                if not npcFolder then return end\n                local f = npcFolder:FindFirstChild("Function")\n                local m = (f and f:FindFirstChild(npcName)) or npcFolder:FindFirstChild(npcName)\n                if m then hrp = m:FindFirstChild("HumanoidRootPart") or m:FindFirstChild("Torso") end\n            end)\n            return hrp\n        end\n\n        local function teleportNearNpc(npcName, offset)\n            local hrp = findNpcHrp(npcName)\n            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")\n            if not hrp or not root then return false end\n            pcall(function()\n                root.CFrame = CFrame.new(hrp.Position + (offset or Vector3.new(0, 3, 0)))\n            end)\n            return true\n        end\n\n        local function parseWeightKg(text)\n            local clean = string.gsub(text, "[,%s]", "")\n            local num, suffix = string.match(clean, "(%d+%.?%d*)([KkMmBbTt]?)")\n            local n = tonumber(num) or 0\n            if suffix == "K" or suffix == "k" then\n                n = n * 1000\n            elseif suffix == "M" or suffix == "m" then\n                n = n * 1000000\n            elseif suffix == "B" or suffix == "b" then\n                n = n * 1000000000\n            elseif suffix == "T" or suffix == "t" then\n                n = n * 1000000000000\n            end\n            return n\n        end\n\n        local function getFishKg(item)\n            local w = 0\n            pcall(function()\n                local attr = item:GetAttribute("Weight")\n                if tonumber(attr) and tonumber(attr) > 0 then\n                    w = tonumber(attr)\n                elseif typeof(item) == "Instance" and typeof(item) == "Instance" and item:IsA("StringValue") then\n                    local parts = {}\n                    for part in string.gmatch(item.Value, "[^|]+") do table.insert(parts, part) end\n                    if #parts >= 2 then w = parseWeightKg(parts[2]) end\n                elseif typeof(item) == "Instance" and typeof(item) == "Instance" and item:IsA("NumberValue") or item:IsA("IntValue") then\n                    w = tonumber(item.Value) or 0\n                end\n            end)\n            return w\n        end\n\n        local function collectBigFish(minKg)\n            local out = {}\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            local inv = userData and userData:FindFirstChild("Inventory")\n            if not inv then return out end\n            for _, item in pairs(inv:GetChildren()) do\n                local kg = getFishKg(item)\n                if kg >= minKg then\n                    table.insert(out, { item = item, name = item.Name, kg = kg })\n                end\n            end\n            table.sort(out, function(a, b) return a.kg > b.kg end)\n            return out\n        end\n\n        local function giveFishToDumbGuy(entry)\n            if not entry or not entry.item then return false end\n            local model = nil\n            pcall(function()\n                local npcFolder = npcRoot()\n                local f = npcFolder and npcFolder:FindFirstChild("Function")\n                model = f and f:FindFirstChild("Dumb guy")\n            end)\n            if not model then return false end\n            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")\n            local origCF = root and root.CFrame\n            if teleportNearNpc("Dumb guy", Vector3.new(0, 3, 0)) then task.wait(0.4) end\n\n            pcall(function() Events.StartDialogue:FireServer("Dumb guy", model) end)\n            task.wait(0.15)\n\n            local fired = false\n            pcall(function()\n                Events.ChooseDialogueOption:FireServer("Dumb guy", 1, "GiveFish", { model })\n                fired = true\n            end)\n\n            if origCF and root and root.Parent then\n                task.wait(0.3)\n                pcall(function() root.CFrame = origCF end)\n            end\n            return fired\n        end\n        GiveSection:CreateButton({\n            Name = "Teleport To Duan Gan NPC",\n            Callback = function()\n                if teleportNearNpc("Duan Gan", Vector3.new(0, 3, 0)) then\n                    NexusLib:Notify({ Title = "Duan Gan", Message = "Teleported!", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = "Duan Gan", Message = "NPC not found!", Duration = 3 })\n                end\n            end\n        })\n\n        GiveSection:CreateButton({\n            Name = "Teleport To Dumb Guy NPC",\n            Callback = function()\n                if teleportNearNpc("Dumb guy", Vector3.new(0, 3, 0)) then\n                    NexusLib:Notify({ Title = "Dumb Guy", Message = "Teleported!", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = "Dumb Guy", Message = "NPC not found!", Duration = 3 })\n                end\n            end\n        })\n\n        GiveSection:CreateButton({\n            Name = "Give 1 Fish > 2M kg",\n            Callback = function()\n                local list = collectBigFish(2000000)\n                if #list == 0 then\n                    NexusLib:Notify({ Title = "Give Fish", Message = "No fish over 2M kg in inventory!", Duration = 3 })\n                    return\n                end\n                local e = list[1]\n                if giveFishToDumbGuy(e) then\n                    NexusLib:Notify({ Title = "Give Fish", Message = "Gave " .. e.name .. " (" .. tostring(e.kg) .. " kg)", Duration = 3 })\n                else\n                    NexusLib:Notify({ Title = "Give Fish", Message = "Failed to give fish!", Duration = 3 })\n                end\n            end\n        })\n\n        NexusState.autoGiveFishRunning = false\n        NexusState.autoGiveFishThread = nil\n\n        Cfg.register(GiveSection:CreateToggle(Cfg.wrap("Toggle", "Auto Give Fish > 2M kg", {\n            Name = "Auto Give Fish > 2M kg",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoGiveFishRunning = value\n                if NexusState.autoGiveFishThread then\n                    pcall(task.cancel, NexusState.autoGiveFishThread)\n                    NexusState.autoGiveFishThread = nil\n                end\n                if not value then return end\n                NexusState.autoGiveFishThread = task.spawn(function()\n                    while NexusState.autoGiveFishRunning do\n                        pcall(function()\n                            local list = collectBigFish(2000000)\n                            if #list > 0 then giveFishToDumbGuy(list[1]) end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            end\n        })), "Toggle", "Auto Give Fish > 2M kg", {\n            Name = "Auto Give Fish > 2M kg",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoGiveFishRunning = value\n                if NexusState.autoGiveFishThread then\n                    pcall(task.cancel, NexusState.autoGiveFishThread)\n                    NexusState.autoGiveFishThread = nil\n                end\n                if not value then return end\n                NexusState.autoGiveFishThread = task.spawn(function()\n                    while NexusState.autoGiveFishRunning do\n                        pcall(function()\n                            local list = collectBigFish(2000000)\n                            if #list > 0 then giveFishToDumbGuy(list[1]) end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            end\n        })\n\n        -- ===== AUTO FARM CA 2M+ KG =====\n        NexusState.autoFarm2MRunning = false\n        NexusState.autoFarm2MThread = nil\n\n        local function findBigKgIsland()\n            local best, bestKg = nil, 0\n            pcall(function()\n                local ra