   Options = {"Z", "X", "C", "V"},\n        Default = {"Z", "X", "C", "V"},\n        Callback = function(values) Fishing.Flags.SelectedSkills = values end\n    })), "MultiDropdown", "Skills to press", {\n        Name = "Skills to press",\n        Options = {"Z", "X", "C", "V"},\n        Default = {"Z", "X", "C", "V"},\n        Callback = function(values) Fishing.Flags.SelectedSkills = values end\n    })\n\n    local EquipSection = FarmingTab:CreateSection("Auto Equip")\n\n    Cfg.register(EquipSection:CreateToggle(Cfg.wrap("Toggle", "Auto Equip Best Bait", {\n        Name = "Auto Equip Best Bait",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipBait = value\n            if value then\n                NexusLib:Notify({ Title = "Auto Equip", Message = "Best bait will be equipped automatically", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = "Auto Equip", Message = "Disabled", Duration = 2 })\n            end\n        end\n    })), "Toggle", "Auto Equip Best Bait", {\n        Name = "Auto Equip Best Bait",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipBait = value\n            if value then\n                NexusLib:Notify({ Title = "Auto Equip", Message = "Best bait will be equipped automatically", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = "Auto Equip", Message = "Disabled", Duration = 2 })\n            end\n        end\n    })\n\n    Cfg.register(EquipSection:CreateToggle(Cfg.wrap("Toggle", "Auto Equip Fishing Rod (Slot 1)", {\n        Name = "Auto Equip Fishing Rod (Slot 1)",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipRod = value\n            if value then\n                NexusLib:Notify({ Title = "Auto Equip Rod", Message = "Will equip rod if not holding", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = "Auto Equip Rod", Message = "Disabled", Duration = 2 })\n            end\n        end\n    })), "Toggle", "Auto Equip Fishing Rod (Slot 1)", {\n        Name = "Auto Equip Fishing Rod (Slot 1)",\n        Default = false,\n        Callback = function(value)\n            MiscFlags.AutoEquipRod = value\n            if value then\n                NexusLib:Notify({ Title = "Auto Equip Rod", Message = "Will equip rod if not holding", Duration = 2 })\n            else\n                NexusLib:Notify({ Title = "Auto Equip Rod", Message = "Disabled", Duration = 2 })\n            end\n        end\n    })\n\n    task.spawn(function()\n        local ToggleHotbar = Events:FindFirstChild("ToggleHotbar")\n        if not ToggleHotbar then return end\n        while task.wait(1) do\n            if not alive() then break end\n            if MiscFlags.AutoEquipRod then\n                pcall(function()\n                    if not isHoldingFishingRod() then\n                        ToggleHotbar:InvokeServer("1", nil)\n                    end\n                end)\n            end\n        end\n    end)\n\n    EquipSection:CreateButton({\n        Name = "Equip Best Rod",\n        Callback = function()\n            local best = GetBestRod()\n            if best then\n                if EquipRod(best) then\n                    NexusLib:Notify({ Title = "Equip Rod", Message = "Equipped best rod: " .. best, Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = "Equip Rod", Message = "Failed to equip rod", Duration = 2 })\n                end\n            else\n                NexusLib:Notify({ Title = "Equip Rod", Message = "No rod available", Duration = 2 })\n            end\n        end\n    })\n\n    EquipSection:CreateButton({\n        Name = "Equip Best Orb",\n        Callback = function()\n            local best = GetBestOrb()\n            if best then\n                if EquipOrb(best) then\n                    NexusLib:Notify({ Title = "Equip Orb", Message = "Equipped best orb: " .. best, Duration = 2 })\n                else\n                    NexusLib:Notify({ Title = "Equip Orb", Message = "Failed to equip orb", Duration = 2 })\n                end\n            else\n                NexusLib:Notify({ Title = "Equip Orb", Message = "No orb available", Duration = 2 })\n            end\n        end\n    })\n\n    task.spawn(function()\n        while task.wait(3) do\n            if MiscFlags.AutoEquipBait then\n                pcall(function()\n                    local userId = LocalPlayer.UserId\n                    local userData = Data:FindFirstChild(tostring(userId))\n                    if not userData then return end\n                    local equippedBaitValue = userData:FindFirstChild("EquippedBait")\n                    if not equippedBaitValue then return end\n                    local currentBait = equippedBaitValue.Value or ""\n                    local best = GetBestBait()\n                    if best and best ~= currentBait then\n                        if EquipBait(best) then\n                            NexusLib:Notify({ Title = "Auto Equip", Message = "Equipped best bait: " .. best, Duration = 2 })\n                        end\n                    end\n                end)\n            end\n        end\n    end)\n\n    -- ===== AUTO NAMELESS OCTOPARASITE =====\n    do\n        local NAMELESS_NAME = "Nameless Octoparasite"\n        local RHY_LANES = { "A", "S", "D" }\n        local RHY_KEYS = { A = Enum.KeyCode.A, S = Enum.KeyCode.S, D = Enum.KeyCode.D }\n        local RHY_WINDOW = 0.22\n        local RHY_SPEED = 1.15 / 1.4\n        local RHY_BAR_FALLBACK = 0.85\n\n        NexusState.Nameless = {\n            Enabled = false,\n            Mode = "Safe",\n            RiskRate = 25,\n            Band = 0.08,\n            Lag = 0.03,\n            Active = false,\n            SignalUntil = 0,\n            Config = nil,\n            Method = nil,\n            RiskThread = nil,\n            NextPress = {},\n            Stats = { hit = 0, spam = 0 },\n        }\n        local Rhy = NexusState.Nameless\n\n        local function rhyFindNameless()\n            local roots = {}\n            local ocean = Workspace:FindFirstChild("Ocean")\n            if ocean then\n                local boss = ocean:FindFirstChild("Boss")\n                if boss then\n                    local fn = boss:FindFirstChild("FishName")\n                    if fn then table.insert(roots, fn) end\n                    table.insert(roots, boss)\n                end\n                table.insert(roots, ocean)\n            end\n            local fishes = Workspace:FindFirstChild("Fishes")\n            if fishes then table.insert(roots, fishes) end\n            for _, root in ipairs(roots) do\n                local ok, found = pcall(function() return root:FindFirstChild(NAMELESS_NAME, true) end)\n                if ok and found then return found end\n            end\n            return nil\n        end\n\n        local function rhyPivotOf(inst)\n            if not inst then return nil end\n            local ok, cf = pcall(function()\n                if typeof(inst) == "Instance" and typeof(inst) == "Instance" and inst:IsA("BasePart") then return inst.CFrame end\n                if typeof(inst) == "Instance" and typeof(inst) == "Instance" and inst:IsA("Model") then\n                    if inst.PrimaryPart then return inst.PrimaryPart.CFrame end\n                    return inst:GetPivot()\n                end\n                local part = inst:FindFirstChildWhichIsA("BasePart", true)\n                if part then return part.CFrame end\n                return nil\n            end)\n            if ok and cf then return cf end\n            return nil\n        end\n\n        local function rhyTeleportToNameless()\n            local model = rhyFindNameless()\n            if not model then\n                NexusLib:Notify({ Title = "Nameless", Message = "Cannot find " .. NAMELESS_NAME .. " in Workspace (boss not spawned yet?)", Duration = 3 })\n                return false\n            end\n            local cf = rhyPivotOf(model)\n            if not cf then\n                NexusLib:Notify({ Title = "Nameless", Message = "Found boss but could not get its position!", Duration = 3 })\n                return false\n            end\n            local char = LocalPlayer.Character\n            local hrp = char and (char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart)\n            if not hrp then\n                NexusLib:Notify({ Title = "Nameless", Message = "Character not found!", Duration = 2 })\n                return false\n            end\n            hrp.CFrame = cf + Vector3.new(0, 12, 0)\n            NexusLib:Notify({ Title = "Nameless", Message = "Teleported to " .. NAMELESS_NAME, Duration = 2 })\n            return true\n        end\n\n        local function rhyPress(laneFrame, lane)\n            local methods = {\n                function()\n                    if not firesignal then return false end\n                    local btn = laneFrame and laneFrame:FindFirstChild("Button")\n                    if not btn then return false end\n                    if not (typeof(btn) == "Instance" and (btn:IsA("TextButton") or btn:IsA("ImageButton"))) then return false end\n                    firesignal(btn.MouseButton1Click)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService("VirtualInputManager")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, game)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, game)\n                    return true\n                end,\n                function()\n                    local vim = game:GetService("VirtualInputManager")\n                    vim:SendKeyEvent(true, RHY_KEYS[lane], false, nil)\n                    vim:SendKeyEvent(false, RHY_KEYS[lane], false, nil)\n                    return true\n                end,\n            }\n            if Rhy.Method then\n                local ok, res = pcall(methods[Rhy.Method])\n                if ok and res then return true end\n                Rhy.Method = nil\n            end\n            for i, fn in ipairs(methods) do\n                local ok, res = pcall(fn)\n                if ok and res then\n                    Rhy.Method = i\n                    return true\n                end\n            end\n            return false\n        end\n\n        local function rhyGui()\n            local fishing = MainGui and MainGui:FindFirstChild("Fishing")\n            if not fishing then return nil, nil end\n            return fishing:FindFirstChild("Rhythm"), fishing\n        end\n\n        local function rhyUiActive()\n            local gui, fishing = rhyGui()\n            if not gui or not fishing then return false end\n            return gui.Visible == true and fishing.Visible == true\n        end\n\n        local function rhyMaxBand()\n            local m = RHY_WINDOW - RHY_SPEED * (Rhy.Lag or 0) - 0.02\n            if m < 0.01 then m = 0.01 end\n            return m\n        end\n\n        local function rhyScan(now)\n            local gui = rhyGui()\n            if not gui then return end\n            for _, lane in ipairs(RHY_LANES) do\n                local laneFrame = gui:FindFirstChild("Progression" .. lane)\n                if laneFrame then\n                    local barY = RHY_BAR_FALLBACK\n                    local barFrame = laneFrame:FindFirstChild("BarFrame")\n                    if barFrame then\n                        local okB, y = pcall(function() return barFrame.Position.Y.Scale end)\n                        if okB and type(y) == "number" then barY = y end\n                    end\n                    local band = math.clamp(Rhy.Band, 0.01, rhyMaxBand())\n                    local inWindow = 0\n                    for _, note in ipairs(laneFrame:GetChildren()) do\n                        if note.Name == "Note_FX" then\n                            local okP, y = pcall(function() return note.Position.Y.Scale end)\n                            if okP and type(y) == "number" then\n                                if math.abs((y + RHY_SPEED * Rhy.Lag) - barY) <= band then\n                                    inWindow = inWindow + 1\n                                end\n                            end\n                        end\n                    end\n                    if inWindow > 5 then inWindow = 5 end\n                    for _ = 1, inWindow do\n                        if rhyPress(laneFrame, lane) then\n                            Rhy.Stats.hit = Rhy.Stats.hit + 1\n                        end\n                    end\n                end\n            end\n        end\n\n        local function rhyStartRisk()\n            if Rhy.RiskThread then return end\n            Rhy.RiskThread = task.spawn(function()\n                while alive() and Rhy.Enabled and Rhy.Mode == "Risk" and Rhy.Active do\n                    local rate = math.clamp(tonumber(Rhy.RiskRate) or 25, 1, 200)\n                    local burst = math.max(1, math.floor(rate / 20))\n                    for _ = 1, burst do\n                        pcall(function() Events.RhythmHit:FireServer("hit") end)\n                        Rhy.Stats.spam = Rhy.Stats.spam + 1\n                    end\n                    task.wait(burst / rate)\n                end\n                Rhy.RiskThread = nil\n            end)\n        end\n\n        if runtimeEnv.NexusRhyStart then pcall(function() runtimeEnv.NexusRhyStart:Disconnect() end) end\n        if runtimeEnv.NexusRhyStop then pcall(function() runtimeEnv.NexusRhyStop:Disconnect() end) end\n        if runtimeEnv.NexusRhyLoop then pcall(function() runtimeEnv.NexusRhyLoop:Disconnect() end) end\n        if runtimeEnv.NexusNamelessBGM then pcall(function() runtimeEnv.NexusNamelessBGM:Disconnect() end) end\n        if runtimeEnv.NexusNamelessP2 then pcall(function() runtimeEnv.NexusNamelessP2:Disconnect() end) end\n\n        pcall(function()\n            local evStart = Events:FindFirstChild("RhythmStart")\n            if evStart then\n                runtimeEnv.NexusRhyStart = evStart.OnClientEvent:Connect(function(cfg)\n                    if not alive() then return end\n                    Rhy.Config = cfg\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    Rhy.Stats = { hit = 0, spam = 0 }\n                    Rhy.NextPress = {}\n                    if Rhy.Enabled then\n                        local hp = cfg and (cfg.FinalMaxHP or cfg.HPFinalPhase)\n                        NexusLib:Notify({\n                            Title = "Auto Nameless",\n                            Message = "Nameless started [" .. tostring(Rhy.Mode) .. "]" .. (hp and (" | HP " .. tostring(hp)) or ""),\n                            Duration = 3,\n                        })\n                        if Rhy.Mode == "Risk" then rhyStartRisk() end\n                    end\n                end)\n            end\n            local evStop = Events:FindFirstChild("RhythmStop")\n            if evStop then\n                runtimeEnv.NexusRhyStop = evStop.OnClientEvent:Connect(function()\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                end)\n            end\n        end)\n\n        -- Nameless remotes captured after kill (remote.txt): BossPhaseBGM(name, sound) + BossPhase2Setup().\n        -- Arm the minigame on either remote so Auto Nameless works even when RhythmStart is late/missing.\n        pcall(function()\n            local evBGM = Events:FindFirstChild("BossPhaseBGM")\n            if evBGM then\n                runtimeEnv.NexusNamelessBGM = evBGM.OnClientEvent:Connect(function(bossName, _sound)\n                    if not alive() then return end\n                    if bossName ~= nil and tostring(bossName) ~= "Nameless Octoparasite"\n                        and tostring(bossName) ~= "Black Tortoise Bloodline" then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = "Auto Nameless", Message = "Nameless boss signal [" .. tostring(Rhy.Mode) .. "]", Duration = 3 })\n                    end\n                end)\n            end\n            local evP2 = Events:FindFirstChild("BossPhase2Setup")\n            if evP2 then\n                runtimeEnv.NexusNamelessP2 = evP2.OnClientEvent:Connect(function()\n                    if not alive() then return end\n                    Rhy.Active = true\n                    Rhy.SignalUntil = tick() + 8\n                    if Rhy.Enabled then\n                        NexusLib:Notify({ Title = "Auto Nameless", Message = "Nameless phase 2 [" .. tostring(Rhy.Mode) .. "]", Duration = 3 })\n                    end\n                end)\n            end\n        end)\n\n\n        runtimeEnv.NexusRhyLoop = RunService.Heartbeat:Connect(function()\n            if not alive() or not Rhy.Enabled then return end\n            local now = tick()\n            Rhy.Active = rhyUiActive() or now < (Rhy.SignalUntil or 0)\n            if not Rhy.Active then return end\n            if Rhy.Mode == "Risk" then rhyStartRisk() end\n            rhyScan(now)\n        end)\n\n        local NamelessSection = FarmingTab:CreateSection("Auto Nameless Octoparasite")\n        NamelessSection:CreateButton({\n            Name = "Teleport to Nameless Octoparasite",\n            Callback = function() pcall(rhyTeleportToNameless) end\n        })\n        Cfg.register(NamelessSection:CreateToggle(Cfg.wrap("Toggle", "Auto Nameless", {\n            Name = "Auto Nameless",\n            Default = false,\n            Callback = function(value)\n                Rhy.Enabled = value\n                if value then\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Enabled [" .. tostring(Rhy.Mode) .. "]. Waiting for Nameless signal from server.", Duration = 3 })\n                    if Rhy.Active and Rhy.Mode == "Risk" then rhyStartRisk() end\n                else\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Disabled | hit " .. tostring(Rhy.Stats.hit) .. " | remote " .. tostring(Rhy.Stats.spam), Duration = 3 })\n                end\n            end\n        })), "Toggle", "Auto Nameless", {\n            Name = "Auto Nameless",\n            Default = false,\n            Callback = function(value)\n                Rhy.Enabled = value\n                if value then\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Enabled [" .. tostring(Rhy.Mode) .. "]. Waiting for Nameless signal from server.", Duration = 3 })\n                    if Rhy.Active and Rhy.Mode == "Risk" then rhyStartRisk() end\n                else\n                    Rhy.Active = false\n                    Rhy.SignalUntil = 0\n                    NexusLib:Notify({ Title = "Auto Nameless", Message = "Disabled | hit " .. tostring(Rhy.Stats.hit) .. " | remote " .. tostring(Rhy.Stats.spam), Duration = 3 })\n                end\n            end\n        })\n    -- ===== AUTO BLACK TORTOISE BLOODLINE =====\n    do\n        local TORTOISE_NAME = "Black Tortoise Bloodline"\n        local autoBossEnabled = {\n            Enzo = NexusState.AutoEnzoEnabled == true or Fishing.Flags.AutoFightEnzo == true,\n            ["Long Diaohai"] = NexusState.AutoLongDiaohaiEnabled == true\n                or Fishing.Flags.AutoLongDiaohai == true,\n            ["Black Tortoise Bloodline"] = false,\n        }\n        local autoBossThreads = {}\n\n        local function isAnyBossMinigameVisible()\n            local fishing = MainGui and MainGui:FindFirstChild("Fishing")\n            local bossBar = fishing and fishing:FindFirstChild("BossFightBar")\n            return bossBar ~= nil and bossBar.Visible == true\n        end\n\n        local function isNamedBossInFight(bossName)\n            local active = false\n            pcall(function()\n                local npc = Workspace:FindFirstChild("NPC")\n                local boss = npc and npc:FindFirstChild(bossName, true)\n                if boss and boss:GetAttribute("InFight") == true then active = true end\n            end)\n            return active or isAnyBossMinigameVisible()\n        end\n\n        local function refreshAutoBossSkillCheck()\n            local anyEnabled = autoBossEnabled.Enzo == true\n                or autoBossEnabled["Long Diaohai"] == true\n                or autoBossEnabled["Black Tortoise Bloodline"] == true\n            NexusState.AutoEnzoEnabled = autoBossEnabled.Enzo == true\n            NexusState.AutoLongDiaohaiEnabled = autoBossEnabled["Long Diaohai"] == true\n            NexusState.AutoBlackTortoiseEnabled = autoBossEnabled["Black Tortoise Bloodline"] == true\n            Fishing.Flags.AutoSkillCheck = anyEnabled\n        end\n\n        local function setAutoBoss(bossName, enabled)\n            enabled = enabled == true\n            autoBossEnabled[bossName] = enabled\n            refreshAutoBossSkillCheck()\n\n            local oldThread = autoBossThreads[bossName]\n            if oldThread then\n                pcall(task.cancel, oldThread)\n                autoBossThreads[bossName] = nil\n            end\n            if not enabled then return end\n            if not StartBossFight then\n                NexusLib:Notify({ Title = "Auto Boss", Message = "StartBossFight remote is unavailable.", Duration = 3 })\n                return\n            end\n\n            MiscFlags.AutoEquipRod = true\n            pcall(function()\n                local toggleHotbar = Events:FindFirstChild("ToggleHotbar")\n                if toggleHotbar and toggleHotbar:IsA("RemoteFunction") then\n                    toggleHotbar:InvokeServer("1", nil)\n                elseif toggleHotbar and toggleHotbar:IsA("RemoteEvent") then\n                    toggleHotbar:FireServer("1", nil)\n                end\n            end)\n\n            autoBossThreads[bossName] = task.spawn(function()\n                local lastRequest = 0\n                while alive() and autoBossEnabled[bossName] do\n                    if not isNamedBossInFight(bossName) and tick() - lastRequest >= 4.0 then\n                        local fightMode = "Normal"\n                        if bossName == "Long Diaohai" then\n                            fightMode = Fishing.Flags.LongDiaohaiFightMode or "Normal"\n                        elseif bossName == "Black Tortoise Bloodline" then\n                            fightMode = "Hard"\n                        else\n                            fightMode = Fishing.Flags.BossFightMode or "Normal"\n                        end\n                        local ok = pcall(function()\n                            StartBossFight:FireServer(bossName, fightMode)\n                        end)\n                        if ok then lastRequest = tick() end\n                        task.wait(4.0)\n                    else\n                        task.wait(0.35)\n                    end\n                end\n                autoBossThreads[bossName] = nil\n            end)\n        end\n\n        local tortoiseFullOn = false\n        local tortoiseMiniOn = false\n        local tortoiseThread = nil\n\n        local function findTortoiseModel()\n            local roots = {}\n            local ocean = Workspace:FindFirstChild("Ocean")\n            if ocean then\n                local boss = ocean:FindFirstChild("Boss")\n                if boss then table.insert(roots, boss) end\n                table.insert(roots, ocean)\n            end\n            local fishes = Workspace:FindFirstChild("Fishes")\n            if fishes then table.insert(roots, fishes) end\n            local npc = Workspace:FindFirstChild("NPC")\n            if npc then table.insert(roots, npc) end\n            table.insert(roots, Workspace)\n            for _, root in ipairs(roots) do\n                local ok, found = pcall(function()\n                    return root:FindFirstChild(TORTOISE_NAME, true)\n                end)\n                if ok and found then return found end\n            end\n            return nil\n        end\n\n        local function tortoisePivot(inst)\n            if not inst then return nil end\n            local ok, cf = pcall(function()\n                if inst:IsA("BasePart") then return inst.CFrame end\n                if inst:IsA("Model") then\n                    if inst.PrimaryPart then return inst.PrimaryPart.CFrame end\n                    return inst:GetPivot()\n                end\n                local part = inst:FindFirstChildWhichIsA("BasePart", true)\n                return part and part.CFrame or nil\n            end)\n            return (ok and cf) or nil\n        end\n\n        local function teleportToTortoise()\n            local model = findTortoiseModel()\n            if not model then return false, "not found" end\n            local cf = tortoisePivot(model)\n            if not cf then return false, "no pivot" end\n            local char = LocalPlayer.Character\n            local hrp = char and char:FindFirstChild("HumanoidRootPart")\n            if not hrp then return false, "no hrp" end\n            pcall(function()\n                hrp.AssemblyLinearVelocity = Vector3.zero\n                hrp.CFrame = cf + Vector3.new(0, 6, 10)\n            end)\n            return true, "ok"\n        end\n\n        local function setTortoiseMinigame(on)\n            tortoiseMiniOn = on == true\n            NexusState.AutoBlackTortoiseMinigame = tortoiseMiniOn\n            setAutoBoss(TORTOISE_NAME, tortoiseMiniOn or tortoiseFullOn)\n            NexusState.AutoBlackTortoiseEnabled = tortoiseMiniOn or tortoiseFullOn\n            if tortoiseMiniOn or tortoiseFullOn then\n                Rhy.Enabled = true\n                Rhy.Mode = "Safe"\n                Rhy.Band = 0.08\n                Rhy.Lag = 0.03\n            elseif not NexusState.AutoEnzoEnabled and not NexusState.AutoLongDiaohaiEnabled then\n                Rhy.Enabled = false\n            end\n        end\n\n        local function stopTortoiseFullLoop()\n            tortoiseFullOn = false\n            if tortoiseThread then\n                pcall(function() task.cancel(tortoiseThread) end)\n                tortoiseThread = nil\n            end\n        end\n\n        local TortoiseSection = FarmingTab:CreateSection("Auto Black Tortoise Bloodline")\n        local teleportConfig = {\n            Name = "Teleport to Black Tortoise Bloodline",\n            Callback = function()\n                local ok, reason = teleportToTortoise()\n                NexusLib:Notify({\n                    Title = "Black Tortoise",\n                    Message = ok and "Teleported to boss." or ("Cannot TP: " .. tostring(reason)),\n                    Duration = 3,\n                })\n            end,\n        }\n        Cfg.register(\n            TortoiseSection:CreateButton(Cfg.wrap("Button", "Teleport to Black Tortoise Bloodline", teleportConfig)),\n            "Button",\n            "Teleport to Black Tortoise Bloodline",\n            teleportConfig\n        )\n\n        local minigameConfig = {\n            Name = "Auto Minigame (Rhythm + QTE)",\n            Default = false,\n            Callback = function(value)\n                setTortoiseMinigame(value == true)\n                NexusLib:Notify({\n                    Title = "Black Tortoise Minigame",\n                    Message = value and "ON - Safe Rhythm and QTE only." or "OFF",\n                    Duration = 3,\n                })\n            end,\n        }\n        Cfg.register(\n            TortoiseSection:CreateToggle(Cfg.wrap("Toggle", "Auto Black Tortoise Minigame", minigameConfig)),\n            "Toggle",\n            "Auto Black Tortoise Minigame",\n      