35770,37247,",\n            Default = selectedTargetTrait,\n            Callback = function(value) selectedTargetTrait = value end\n        })\n\n        local ignoreLockedToggle = Cfg.register(TraitSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Ignore Locked\", {\n            Name = \"Ignore Locked\",\n            Default = false,\n            Callback = function(value) ignoreLocked = value end\n        })), \"Toggle\", \"Ignore Locked\", {\n            Name = \"Ignore Locked\",\n            Default = false,\n            Callback = function(value) ignoreLocked = value end\n        })\n\n        local rerollMethodDropdown = Cfg.register(TraitSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Reroll Method\", {\n            Name = \"Reroll Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.Reroll.method or \"Instant\",\n            Callback = function(value) NexusState.Reroll.method = value end\n        })), \"Dropdown\", \"Reroll Method\", {\n            Name = \"Reroll Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = NexusState.Reroll.method or \"Instant\",\n            Callback = function(value) NexusState.Reroll.method = value end\n        })\n\n        local RerollTrait = Events:FindFirstChild(\"RerollTrait\")\n\n        TraitSection:CreateButton({\n            Name = \"Reroll Until Trait\",\n            Callback = function()\n                if NexusState.Reroll.running then\n                    NexusState.Reroll.running = false\n                    if NexusState.Reroll.thread then\n                        task.cancel(NexusState.Reroll.thread)\n                        NexusState.Reroll.thread = nil\n                    end\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild(\"HumanoidRootPart\")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Stopped\", Duration = 2 })\n                    return\n                end\n\n                local skillName = selectedSkillForReroll\n                local targetTrait = selectedTargetTrait\n                if not skillName or skillName == \"\" or skillName == \"No skill owned\" then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Select a valid skill\", Duration = 2 })\n                    return\n                end\n                if not targetTrait or targetTrait == \"\" or targetTrait == \"No trait available\" then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Select a target trait\", Duration = 2 })\n                    return\n                end\n                if not RerollTrait then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"RerollTrait event not found\", Duration = 2 })\n                    return\n                end\n                local p = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                local rerollCount = p and p:FindFirstChild(\"Trait Reroll\")\n                if rerollCount and rerollCount.Value <= 0 then\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"No rerolls left!\", Duration = 2 })\n                    return\n                end\n\n                NexusState.Reroll.teleported = false\n                NexusState.Reroll.oldPosition = nil\n                if NexusState.Reroll.method == \"Teleport\" then\n                    local npc = Workspace:FindFirstChild(\"NPC\")\n                    if npc then\n                        local func = npc:FindFirstChild(\"Function\")\n                        if func then\n                            local nanjiang = func:FindFirstChild(\"Nanjiang\")\n                            if typeof(nanjiang) == \"Instance\" and nanjiang:IsA(\"Model\") then\n                                local hrp = nanjiang:FindFirstChild(\"HumanoidRootPart\")\n                                if hrp then\n                                    local char = LocalPlayer.Character\n                                    if char then\n                                        local root = char:FindFirstChild(\"HumanoidRootPart\")\n                                        if root then\n                                            NexusState.Reroll.oldPosition = root.Position\n                                            root.CFrame = CFrame.new(hrp.Position + Vector3.new(0, 3, 0))\n                                            NexusState.Reroll.teleported = true\n                                            task.wait(0.3)\n                                        end\n                                    end\n                                end\n                            end\n                        end\n                    end\n                    if not NexusState.Reroll.teleported then\n                        NexusLib:Notify({ Title = \"Reroll\", Message = \"Could not find Nanjiang, teleport failed. Continuing anyway.\", Duration = 3 })\n                    end\n                end\n\n                NexusState.Reroll.running = true\n                NexusLib:Notify({ Title = \"Reroll\", Message = \"Reroll started... Target: \" .. targetTrait, Duration = 2 })\n\n                NexusState.Reroll.thread = task.spawn(function()\n                    local successCount = 0\n                    while NexusState.Reroll.running do\n                        local p2 = Data and Data:FindFirstChild(tostring(LocalPlayer.UserId))\n                        local count = p2 and p2:FindFirstChild(\"Trait Reroll\")\n                        if count and count.Value <= 0 then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"No rerolls left, stopping\", Duration = 2 })\n                            break\n                        end\n                        local success, result = pcall(function()\n                            return RerollTrait:InvokeServer(skillName, ignoreLocked)\n                        end)\n                        if not success or not result then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"Reroll failed, stopping\", Duration = 2 })\n                            break\n                        end\n                        successCount = successCount + 1\n                        local traitName = result.Name\n                        if traitName == targetTrait then\n                            NexusLib:Notify({ Title = \"Reroll\", Message = \"Got \" .. targetTrait .. \" on \" .. skillName .. \" after \" .. successCount .. \" rerolls!\", Duration = 3 })\n                            break\n                        end\n                        task.wait(0.15)\n                    end\n\n                    if NexusState.Reroll.teleported and NexusState.Reroll.oldPosition then\n                        local char = LocalPlayer.Character\n                        if char then\n                            local root = char:FindFirstChild(\"HumanoidRootPart\")\n                            if root then\n                                root.CFrame = CFrame.new(NexusState.Reroll.oldPosition)\n                                NexusState.Reroll.oldPosition = nil\n                                NexusState.Reroll.teleported = false\n                            end\n                        end\n                    end\n                    NexusState.Reroll.running = false\n                    NexusState.Reroll.thread = nil\n                    NexusLib:Notify({ Title = \"Reroll\", Message = \"Stopped\", Duration = 2 })\n                end)\n            end\n        })\n    end\n\n    -- Craft Bait\n    do\n        local CraftSection = ShopTab:CreateSection(\"Craft Bait\")\n        Cfg.register(CraftSection:CreateTextbox(Cfg.wrap(\"Textbox\", \"Number of baits to craft\", {\n            Name = \"Number of baits to craft\",\n            Placeholder = \"1\",\n            Default = \"1\",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })), \"Textbox\", \"Number of baits to craft\", {\n            Name = \"Number of baits to craft\",\n            Placeholder = \"1\",\n            Default = \"1\",\n            Callback = function(value)\n                local num = tonumber(value)\n                if num and num >= 1 then\n                    NexusState.craftBaitQuantity = math.floor(num)\n                else\n                    NexusState.craftBaitQuantity = 1\n                end\n            end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Choose a Bait\", {\n            Name = \"Choose a Bait\",\n            Options = {\"Rainbow Bait\", \"Frost Bait\", \"Nameless Bait\"},\n            Default = \"Rainbow Bait\",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })), \"Dropdown\", \"Choose a Bait\", {\n            Name = \"Choose a Bait\",\n            Options = {\"Rainbow Bait\", \"Frost Bait\", \"Nameless Bait\"},\n            Default = \"Rainbow Bait\",\n            Callback = function(value) NexusState.craftBaitName = value end\n        })\n\n        Cfg.register(CraftSection:CreateDropdown(Cfg.wrap(\"Dropdown\", \"Craft Method\", {\n            Name = \"Craft Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = \"Instant\",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })), \"Dropdown\", \"Craft Method\", {\n            Name = \"Craft Method\",\n            Options = {\"Instant\", \"Teleport\"},\n            Default = \"Instant\",\n            Callback = function(value) NexusState.craftBaitMethod = value end\n        })\n\n        local BAIT_RECIPES = {\n            [\"Rainbow Bait\"] = {\n                {name = \"Colossal Tigerfish\", minKg = 3000000, maxKg = 6000000},\n                {name = \"Heavenpiercer Turtle\", minKg = 3000000, maxKg = 6000000},\n                {name = \"Golden Guardian Fish\", minKg = 1000000, maxKg = 3000000},\n                {name = \"Crimson Electric Eel\", minKg = 3000000, maxKg = 4000000},\n            },\n            [\"Frost Bait\"] = {\n                {name = \"Frost Kingfish\", minKg = 4000000, maxKg = 7000000},\n                {name = \"Ascended Perch\", minKg = 900000, maxKg = 1000000},\n                {name = \"Primordial Kunfish Overlord\", minKg = 1000000, maxKg = 1600000},\n                {name = \"Warbringer Shark\", minKg = 500000, maxKg = 800000},\n            },\n            [\"Nameless Bait\"] = {\n                {name = \"Mountain Fish\", minKg = 1000000, maxKg = 5000000},\n                {name = \"Tiger Mirefish\", minKg = 1000000, maxKg = 3000000},\n                {name = \"Mirage Lanternfish\", minKg = 3000000, maxKg = 5000000},\n                {name = \"Octoparasitic Fish\", minKg = 3000000, maxKg = 5000000},\n            }\n        }\n\n        local function checkMaterials(baitName, quantity)\n            local recipe = BAIT_RECIPES[baitName]\n            if not recipe then return false, \"No recipe found for \" .. baitName end\n            local userData = Data:FindFirstChild(tostring(LocalPlayer.UserId))\n            if not userData then return false, \"Player data not found\" end\n            local inventory = userData:FindFirstChild(\"Inventory\")\n            if not inventory then return false, \"Inventory not found\" end\n            local fishCount = {}\n            for _, req in ipairs(recipe) do fishCount[req.name] = 0 end\n            for  conn = npcAddedConn })\n                end\n                \n                npcEspThread = task.spawn(function()\n                    while npcEspEnabled do\n                        task.wait(10)\n                        if npcEspEnabled then\n                            pcall(function()\n                                for model, data in pairs(npcEspHighlights) do\n                                    if not model.Parent then\n                                        removeNpcEsp(model)\n                                    end\n                                end\n                                scanAllNpcs()\n                            end)\n                        end\n                    end\n                end)\n                \n                NexusLib:Notify({ Title = \"NPCs ESP\", Message = \"NPCs ESP enabled!\", Duration = 2 })\n            end\n            \n            local function stopNpcEsp()\n                npcEspEnabled = false\n                if npcEspThread then\n                    task.cancel(npcEspThread)\n                    npcEspThread = nil\n                end\n                clearAllNpcEsp()\n                NexusLib:Notify({ Title = \"NPCs ESP\", Message = \"NPCs ESP disabled!\", Duration = 2 })\n            end\n            \n            Cfg.register(EspSection:CreateToggle(Cfg.wrap(\"Toggle\", \"NPCs ESP\", {\n                Name = \"NPCs ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startNpcEsp()\n                    else\n                        stopNpcEsp()\n                    end\n                end\n            })), \"Toggle\", \"NPCs ESP\", {\n                Name = \"NPCs ESP\",\n                Default = false,\n                Callback = function(value)\n                    if value then\n                        startNpcEsp()\n                    else\n                        stopNpcEsp()\n                    end\n                end\n            })\n        end\n    end\nend\n\n-- ============================================================\n-- ===== DEFINE _G.codetorun AND _G.codes =====\n-- ============================================================\n\n_G.codetorun = [[\n    -- Use the globals assigned by the main script\n    local RunService = _G.RunService\n    local LocalPlayer = _G.LocalPlayer\n    local UserInputService = _G.UserInputService\n    local VirtualUser = _G.VirtualUser\n    local Events = _G.Events\n    local MiscFlags = _G.MiscFlags\n    local alive = _G.alive\n    local runtimeEnv = _G.runtimeEnv\n\n    local noclipAccum = 0\n    if runtimeEnv.NexusNoclipConn then pcall(function() runtimeEnv.NexusNoclipConn:Disconnect() end) end\n    runtimeEnv.NexusNoclipConn = RunService.Stepped:Connect(function(_, dt)\n        if not alive() then return end\n        if not MiscFlags.Noclip then return end\n        noclipAccum = noclipAccum + (dt or 0.016)\n        if noclipAccum < 0.4 then return end\n        noclipAccum = 0\n        local char = LocalPlayer.Character\n        if char then\n            for _, v in ipairs(char:GetDescendants()) do\n                if typeof(v) == \"Instance\" and v:IsA(\"BasePart\") and v.CanCollide then v.CanCollide = false end\n            end\n        end\n    end)\n\n    UserInputService.JumpRequest:Connect(function()\n        if MiscFlags.InfiniteJump and LocalPlayer.Character then\n            local h = LocalPlayer.Character:FindFirstChildOfClass('Humanoid')\n            if h then h:ChangeState(Enum.HumanoidStateType.Jumping) end\n        end\n    end)\n\n    local function nudgeInput()\n        if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then return end\n        local _nm = false\n        pcall(function()\n            local _c = LocalPlayer.Character\n            local _h = _c and _c:FindFirstChildOfClass(\"Humanoid\")\n            local _md = _h and _h.MoveDirection\n            if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _nm = true end\n        end)\n        if _nm then return end\n        pcall(function()\n            if Events and Events:FindFirstChild(\"AFK\") then\n                Events.AFK:FireServer()\n            end\n            if VirtualUser then\n                VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                task.wait(0.2)\n                VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n            end\n        end)\n    end\n\n    if runtimeEnv.AntiAFKConnection then pcall(function() runtimeEnv.AntiAFKConnection:Disconnect() end) end\n    runtimeEnv.AntiAFKConnection = LocalPlayer.Idled:Connect(function()\n        if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then return end\n        nudgeInput()\n    end)\n\n    -- Anti-AFK loop: FireServer + ClickButton2, skipped while moving\n    task.spawn(function()\n        while task.wait(30) do\n            if not alive() then break end\n            local _afkOn = true\n            pcall(function()\n                if _G.Fishing and _G.Fishing.Flags and not _G.Fishing.Flags.AntiAFK then _afkOn = false end\n            end)\n            if _afkOn then\n            local _afkHold = false\n            pcall(function()\n                local _c = LocalPlayer.Character\n                local _h = _c and _c:FindFirstChildOfClass(\"Humanoid\")\n                local _md = _h and _h.MoveDirection\n                if _md and (math.abs(_md.X or 0) + math.abs(_md.Z or 0) > 0.05) then _afkHold = true end\n            end)\n            if not _afkHold then\n            pcall(function()\n                local ev = Events and Events:FindFirstChild(\"AFK\")\n                if ev then\n                    ev:FireServer(\"Stay Active\")\n                end\n            end)\n            end\n            end\n            pcall(function()\n                if VirtualUser and workspace.CurrentCamera then\n                    VirtualUser:Button2Down(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                    task.wait(0.2)\n                    VirtualUser:Button2Up(Vector2.new(0, 0), workspace.CurrentCamera.CFrame)\n                end\n            end)\n        end\n    end)\n\n    task.spawn(function()\n        while task.wait(120) do\n            if not alive() then break end\n            pcall(function()\n                game:GetService(\"RunService\").Heartbeat:Wait()\n            end)\n        end\n    end)\n]]\n\n_G.codes = [[\n    local HttpService = game:GetService(\"HttpService\")\n    local SPIRIT_WEBHOOK = \"https://discord.com/api/webhooks/1537057488673964162/5MMaOipIfBz0GoLEKrGXLZLQf-eZ3hlLVuAENGcFow5BW89BsR_HOVGWijAFmgntmd2I\"\n    local MAOSHAN_WEBHOOK = \"https://discord.com/api/webhooks/1536703114911031348/--tVtcHb36SeM1VkDvxZzTqJOrzbRdaafPb2iRNervYtNT4sbRx_1CAh9QJhIjB9mUI8\"\n    local TAOIST_WEBHOOK = \"https://discord.com/api/webhooks/1536703230573023323/iHOtL846ghztEeWL-NOHdTqAB10eHhRt1Jd34k0H-tmu-1zOAc7SWYzLirOfXgMlNoOV\"\n    local WEATHER_WEBHOOK = \"https://discord.com/api/webhooks/1536240273040998461/EvM4E_BUCyOyQtLuv-YFMpEEa_GsUUYd2618qlv0vBF4r5no0BzGowZ8EH436gclLdYG\"\n    local SERVER_HOP_API_BASE = (_G.NexusState and _G.NexusState.serverHopApiBase) or \"http://103.28.35.190:8000\"\n    local SERVER_HOP_API_KEY = (_G.NexusState and _G.NexusState.serverHopApiKey) or \"\"\n\n    local ScanMaoshan = true\n    local ScanTaoist = true\n    local ScanWeather = true\n    local ScanSpirit = true\n\n    -- Read the assigned globals\n    local Players = _G.Players\n    local Workspace = _G.Workspace\n    local Lighting = _G.Lighting\n    local NexusState = _G.NexusState\n    local alive = _G.alive\n    local LocalPlayer = _G.LocalPlayer\n\n    local b64chars_enc = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'\n    local function b64encode_wh(data)\n        return ((data:gsub('.', function(x)\n            local r,b='',x:byte()\n            for i=8,1,-1 do r=r..(b%2^i-b%2^(i-1)>0 and '1' or '0') end\n            return r;\n        end)..'0000'):gsub('%d%d%d?%d?%d?%d?', function(x)\n            if (#x < 6) then return '' end\n            local c=0\n            for i=1,6 do c=c+(x:sub(i,i)=='1' and 2^(6-i) or 0) end\n            return b64chars_enc:sub(c+1,c+1)\n        end)..({ '', '==', '=' })[#data%3+1])\n    end\n\n    local function sendDiscordWebhook(url, eventName)\n        local httpRequest = (typeof(request) == \"function\" and request) or (typeof(http_request) == \"function\" and http_request) or (syn and typeof(syn.request) == \"function\" and syn.request) or (http and typeof(http.request) == \"function\" and http.request)\n        if not httpRequest or url == \"\" then return end\n        local jobId = game.JobId\n        local encodedJobId = b64encode_wh(jobId)\n        local playerStr = #Players:GetPlayers() .. \"/\" .. Players.MaxPlayers\n        local timeStr = os.date(\"%Y-%m-%d %H:%M:%S\")\n        local payload = HttpService:JSONEncode({\n            username = \"Nexus Hub\",\n            content = \"\",\n            embeds = {{\n                title = \" \" .. eventName .. \" Found!\",\n                description = \"An event NPC has just appeared in the server. Join fast!\",\n                color = 0xFF6B35,\n                fields = {\n                    { name = \" Join Server (tap to copy)\", value = \"NEXUSHUB|\" .. encodedJobId, inline = false },\n                    { name = \" Players\", value = \"`\" .. playerStr .. \"`\", inline = true },\n                    { name = \" Time\", value = \"`\" .. timeStr .. \"`\", inline = true },\n                },\n                footer = { text = \"Nexus Hub Event Scanner\" },\n                timestamp = os.date(\"!%Y-%m-%dT%H:%M:%SZ\"),\n            }}\n        })\n        pcall(function()\n            task.spawn(httpRequest, {\n                Url = url,\n                Method = \"POST\",\n                Headers = { [\"Content-Type\"] = \"application/json\" },\n                Body = payload,\n            })\n        end)\n    end\n\n    local function sendServerEvent(eventName, attributes)\n        local httpRequest = (typeof(request) == \"function\" and request) or (typeof(http_request) == \"function\" and http_request) or (syn and typeof(syn.request) == \"function\" and syn.request) or (http and typeof(http.request) == \"function\" and http.request)\n        if not httpRequest or SERVER_HOP_API_BASE == \"\" then return false end\n        local body = HttpService:JSONEncode({ event_id = tostring(eventName) .. \"-\" .. tostring(os.time()), place_id = game.PlaceId, job_id = game.JobId, reason = tostring(eventName), attributes = attributes or {}, source = \"nexus_hub\" })\n        local ok = pcall(httpRequest, { Url = SERVER_HOP_API_BASE:gsub(\"/$\", \"\") .. \"/v1/hop-events\", Method = \"POST\", Headers = { [\"Content-Type\"] = \"application/json\", [\"X-API-Key\"] = SERVER_HOP_API_KEY }, Body = body })\n        return ok\n    end\n\n    local function sendWeatherWebhook(url, weatherName)\n        local httpRequest = (typeof(request) == \"function\" and request) or (typeof(http_request) == \"function\" and http_request) or (syn and typeof(syn.request) == \"function\" and syn.request) or (http and typeof(http.request) == \"function\" and http.request)\n        if not httpRequest or url == \"\" then return end\n        local jobId = game.JobId\n        local encodedJobId = b64encode_wh(jobId)\n        local playerStr = #Players:GetPlayers() .. \"/\" .. Players.MaxPlayers\n        local timeStr = os.date(\"%Y-%m-%d %H:%M:%S\")\n        local weatherEmoji = {\n            [\"Rainy\"] = \"\", [\"Thunderstorm\"] = \"\", [\"Foggy\"] = \"\",\n            [\"Windy\"] = \"\", [\"Snowy\"] = \"\", [\"Blazing Sun\"] = \"\"\n        }\n        local colors = {\n            [\"Rainy\"] = 0x2A75BB, [\"Thunderstorm\"] = 0x800080, [\"Foggy\"] = 0x808080,\n            [\"Windy\"] = 0x87CEEB, [\"Snowy\"] = 0xFFFAFA, [\"Blazing Sun\"] = 0xFF4500\n        }\n        local emoji = weatherEmoji[weatherName] or \"\"\n        local embedColor = colors[weatherName] or 0x00A2FF\n NexusState.autoGiveFishThread = task.spawn(function()\n                    while NexusState.autoGiveFishRunning do\n                        pcall(function()\n                            local list = collectBigFish(2000000)\n                            if #list > 0 then giveFishToDumbGuy(list[1]) end\n                        end)\n                        task.wait(2)\n                    end\n                end)\n            end\n        })\n\n        -- ===== AUTO FARM CA 2M+ KG =====\n        NexusState.autoFarm2MRunning = false\n        NexusState.autoFarm2MThread = nil\n\n        local function findBigKgIsland()\n            local best, bestKg = nil, 0\n            pcall(function()\n                local rarity = Info:FindFirstChild(\"FishingAreaRarity\")\n                if not rarity then return end\n                for _, area in pairs(rarity:GetChildren()) do\n                    local maxKg = area:FindFirstChild(\"MaxKg\")\n                    local v = maxKg and tonumber(maxKg.Value) or 0\n                    if v >= 2000000 and v > bestKg then\n                        bestKg = v\n                        best = area.Name\n                    end\n                end\n            end)\n            return best, bestKg\n        end\n\n        Cfg.register(GiveSection:CreateToggle(Cfg.wrap(\"Toggle\", \"Auto Farm 2M+ kg Fish\", {\n            Name = \"Auto Farm 2M+ kg Fish\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoFarm2MRunning = value\n                if NexusState.autoFarm2MThread then\n                    pcall(task.cancel, NexusState.autoFarm2MThread)\n                    NexusState.autoFarm2MThread = nil\n                end\n                if not value then return end\n\n                local islandName, kg = findBigKgIsland()\n                if islandName then\n                    for _, isl in ipairs(NexusState.islands) do\n                        if isl.name == islandName then\n                            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                            if root then pcall(function() root.CFrame = isl.cframe end) end\n                            break\n                        end\n                    end\n                    NexusLib:Notify({\n                        Title = \"Auto Farm 2M+\",\n                        Message = \"Farming at \" .. islandName .. \" (max \" .. tostring(kg) .. \" kg)\",\n                        Duration = 3\n                    })\n                else\n                    NexusLib:Notify({ Title = \"Auto Farm 2M+\", Message = \"No 2M+ zone found, farming here.\", Duration = 3 })\n                end\n\n                NexusState.autoFarm2MThread = task.spawn(function()\n                    while NexusState.autoFarm2MRunning do\n                        pcall(function()\n                            local c = LocalPlayer.Character\n                            if c and not c:GetAttribute(\"Fishing\") and NexusState.canCastNow() then\n                                Events.Fishing:FireServer()\n                            end\n                        end)\n                        task.wait(0.6)\n                    end\n                end)\n            end\n        })), \"Toggle\", \"Auto Farm 2M+ kg Fish\", {\n            Name = \"Auto Farm 2M+ kg Fish\",\n            Default = false,\n            Callback = function(value)\n                NexusState.autoFarm2MRunning = value\n                if NexusState.autoFarm2MThread then\n                    pcall(task.cancel, NexusState.autoFarm2MThread)\n                    NexusState.autoFarm2MThread = nil\n                end\n                if not value then return end\n\n                local islandName, kg = findBigKgIsland()\n                if islandName then\n                    for _, isl in ipairs(NexusState.islands) do\n                        if isl.name == islandName then\n                            local root = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                            if root then pcall(function() root.CFrame = isl.cframe end) end\n                            break\n                        end\n                    end\n                    NexusLib:Notify({\n                        Title = \"Auto Farm 2M+\",\n                        Message = \"Farming at \" .. islandName .. \" (max \" .. tostring(kg) .. \" kg)\",\n                        Duration = 3\n                    })\n                else\n                    NexusLib:Notify({ Title = \"Auto Farm 2M+\", Message = \"No 2M+ zone found, farming here.\", Duration = 3 })\n                end\n\n                NexusState.autoFarm2MThread = task.spawn(function()\n                    while NexusState.autoFarm2MRunning do\n                        pcall(function()\n                            local c = LocalPlayer.Character\n                            if c and not c:GetAttribute(\"Fishing\") and NexusState.canCastNow() then\n                                Events.Fishing:FireServer()\n                            end\n                        end)\n                        task.wait(0.6)\n                    end\n                end)\n            end\n        })\n    end\n\n    local weatherIslands = {\n        [\"foggy\"] = \"Island 7\", [\"blazing sun\"] = \"Island 8\", [\"snowy\"] = \"Island 6\",\n        [\"windy\"] = \"Island 5\", [\"rainy\"] = \"Island 3\", [\"thunderstorm\"] = \"Island 2\"\n    }\n\n    local function getCurrentWeather()\n        local info = MainGui:FindFirstChild(\"Info\")\n        if info then\n            local infoFrame = info:FindFirstChild(\"Info\")\n            if infoFrame then\n                local weatherFrame = infoFrame:FindFirstChild(\"Weather\")\n                if weatherFrame then\n                    local val = weatherFrame:FindFirstChild(\"Value\")\n                    if val and typeof(val) == \"Instance\" then\n                        local text = ((typeof(val) == \"Instance\" and val:IsA(\"TextLabel\") and val.Text or val.Value))\n                        return text:gsub(\"Weather:%s*\", \"\")\n                    end\n                end\n            end\n        end\n        return \"Clear\"\n    end\n\n    TPSection:CreateButton({\n        Name = \"Teleport To Current Weather\",\n        Callback = function()\n            local currentWeather = getCurrentWeather()\n            if currentWeather:lower() == \"clear\" or currentWeather == \"\" then\n                NexusLib:Notify({ Title = \"Weather TP\", Message = \"Server weather is Clear, no event to TP!\", Duration = 3 })\n                return\n            end\n            local targetIslandName = weatherIslands[currentWeather:lower()]\n            if targetIslandName then\n                for _, v in ipairs(NexusState.islands) do\n                    if v.name:lower() == targetIslandName:lower() then\n                        local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                        if hrp then\n                            hrp.CFrame = CFrame.new(v.cframe.Position) + Vector3.new(0, 5, 0)\n                            NexusLib:Notify({ Title = \"Weather TP\", Message = \"Teleported to \" .. targetIslandName .. \" for \" .. currentWeather, Duration = 4 })\n                        end\n                        return\n                    end\n                end\n            else\n                NexusLib:Notify({ Title = \"Weather TP\", Message = \"Unknown weather island mapping for: \" .. currentWeather, Duration = 4 })\n            end\n        end\n    })\n\n    -- Server\n    do\n        local ServerSection = TeleportTab:CreateSection(\"Server\", \"Left\")\n        local b64chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'\n        local function b64decode(data)\n            data = string.gsub(data, '[^'..b64chars..'=]', '')\n            return (data:gsub('.', function(x)\n                if (x == '=') then return '' end\n                local r,f='',(b64chars:find(x, 1, true)-1)\n                for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end\n                return r;\n            end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)\n                if (#x ~= 8) then return '' end\n                local c=0\n                for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end\n                return string.char(c)\n            end))\n        end\n\n        local savedJobId = \"\"\n        local lastHopAt = 0\n        ServerSection:CreateTextbox({\n            Name = \"Join by Job ID\",\n            Placeholder = \"Paste Job ID here...\",\n            Default = \"\",\n            Callback = function(text)\n                if text and text ~= \"\" then\n                    local finalJobId = text\n                    local matchB64 = string.match(text, \"NEXUSHUB|([^%s]+)\")\n                    if matchB64 then\n                        local success, decoded = pcall(b64decode, matchB64)\n                        if success and decoded and decoded ~= \"\" then\n                            finalJobId = decoded\n                        end\n                    end\n                    if finalJobId == game.JobId then\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = \"Already in this server.\", Duration = 3 })\n                        return\n                    end\n                    if tick() - lastHopAt < 30 then\n                        NexusLib:Notify({ Title = \"Server Hop\", Message = \"Hop cooldown, try again shortly.\", Duration = 3 })\n                        return\n                    end\n                    lastHopAt = tick()\n                    savedJobId = finalJobId\n                    NexusLib:Notify({ Title = \"Server Hop\", Message = \"Joining server...\", Duration = 3 })\n                    Services.TeleportService:TeleportToPlaceInstance(game.PlaceId, finalJobId, LocalPlayer)\n                end\n            end\n        })\n        ServerSection:CreateButton({\n            Name = \"Delete Job ID\",\n            Callback = function()\n                savedJobId = \"\"\n                NexusLib:Notify({ Title = \"Server Hop\", Message = \"Job ID cleared!\", Duration = 2 })\n            end\n        })\n    end\n\n    -- Islands\n    do\n        local IslandSection = TeleportTab:CreateSection(\"Islands\", \"Right\")\n        for _, v in ipairs(NexusState.islands) do\n            IslandSection:CreateButton({\n                Name = v.name,\n                Callback = function()\n                    local hrp = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild(\"HumanoidRootPart\")\n                    if hrp then\n                        hrp.CFrame = CFrame.new(v.cframe.Position) + Vector3.new(0, 5, 0)\n                        NexusLib:Notify({ Title = \"Teleport\", Message = \"Teleported to \" .. v.name, Duration = 3 })\n                    end\n                end\n            })\n        end\n    end\n    -- ===== PLAYERS SECTION =====\n    do\n        local PlayerSection = TeleportTab:CreateSection(\"Players\", \"Right\")\n        \n        local selectedPlayer = nil\n        local playerDropdown = nil  -- Keep a reference to the dropdown\n        local playerList = {}\n        \n        -- List refresh helper\n        local function refreshPlayerList()\n            -- Read the player list\n            playerList = {}\n            for _, playe